import { Article, ThemesData, Summary } from './types';

export const analysis = `{\"summary\":{\"splosno\":\"Medijsko poro\u010Danje v dneh pred referendumom o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja (ZPPK\u017D) zaznamuje izrazita polarizacija med medicinsko stroko, verskimi skupnostmi in zagovorniki civilne dru\u017Ebe. Osrednji mediji, kot sta Delo in N1, poro\u010Dajo o nara\u0161\u010Dajo\u010Dih napetostih zaradi aktivne vklju\u010Ditve Katoli\u0161ke cerkve v kampanjo, kar je spro\u017Eilo prijave na in\u0161pektorat s strani zavezni\u0161tva Moje \u017Eivljenje, moja pravica. Hkrati zdravni\u0161ke organizacije na skupnih konferencah stopnjujejo nasprotovanje, \u010De\u0161 da zakon ru\u0161i temelje medicinske etike, medtem ko kolumnisti, kot je Alojz Ihan, opozarjajo na nevarnost prisile zdravstvenih delavcev v vlogo izvr\u0161evalcev.\\n\\nNa drugi strani mediji, kot sta Mladina in Slovenske novice, izpostavljajo argumente o osebni avtonomiji in pravici do dostojanstvenega konca brez nepotrebnega trpljenja. Poro\u010Danje vklju\u010Duje tudi tehni\u010Dne informacije o pred\u010Dasnem glasovanju, ki ga napoveduje portal gov.si, ter analize postopkovnih varovalk, ki naj bi prepre\u010Devale zlorabe. Razprava se je raz\u0161irila tudi na vpra\u0161anje lo\u010Denosti cerkve in dr\u017Eave, kjer podporniki zakona opozarjajo na neprimerno vme\u0161avanje verskih voditeljev v zakonodajne postopke.\",\"nasprotniki\":\"Nasprotniki zakona, ki jih vodijo Zdravni\u0161ka zbornica Slovenije, Komisija za medicinsko etiko in vrh Rimskokatoli\u0161ke cerkve (RKC), zakon ozna\u010Dujejo za nevaren 'dru\u017Ebeni eksperiment' in 'kulturo smrti'. Glavni narativi, ki se pojavljajo v medijih Nova24tv, Demokracija in Dru\u017Eina, poudarjajo, da zakon sili zdravnike v dejanja, ki so v nasprotju s Hipokratovo prisego. Izpostavljajo t. i. 'spolzki klanec', kjer bi evtanazija zaradi finan\u010Dnih prihrankov postala alternativa paliativni oskrbi, ranljivi pa bi se po\u010Dutili kot breme dru\u017Ebi. Nad\u0161kof Stanislav Zore in moralni teolog Ivan \u0160tuhec opozarjata na ustavno nedotakljivost \u017Eivljenja, pri \u010Demer se pojavljajo tudi ostre zgodovinske vzporednice z nacisti\u010Dnimi programi.\\n\\nZdravniki, kot so Maja Ebert Moltara, Bojanka \u0160tern in Alenka Forte, opozarjajo na nejasne definicije 'neznosnega trpljenja' in sistemske pomanjkljivosti, kot je pomanjkanje osebnih zdravnikov. Kritiki iz vrst opozicije (SDS) in zdru\u017Eenj, kot sta Usidrani ter Zdru\u017Eenje starih star\u0161ev (Metka Zevnik), poudarjajo, da bi morala dr\u017Eava prednostno urediti paliativno in dolgotrajno oskrbo. Izpostavljajo tudi eti\u010Dno dilemo navajanja neresni\u010Dnih vzrokov smrti v uradnih poro\u010Dilih ter psiholo\u0161ki pritisk na kroni\u010Dne bolnike.\",\"podporniki\":\"Podporniki zakona, zdru\u017Eeni v zavezni\u0161tvu Moje \u017Eivljenje, moja pravica, ki vklju\u010Duje dru\u0161tvo Srebrna nit, stranko Pirati in koalicijske stranke (Gibanje Svoboda, SD, Levica), poudarjajo pravico posameznika do avtonomije in dostojanstvenega konca. Andrej Pleterski, soavtor zakona, in dr. Du\u0161an Keber izpostavljata, da zakon prina\u0161a humano re\u0161itev za tiste, ki jim paliativna oskrba ne more ve\u010D laj\u0161ati neznosnega trpljenja. Zagovorniki v medijih, kot je Mladina, argumentirajo, da pomo\u010D pri kon\u010Danju \u017Eivljenja ne kr\u0161i bistva medicine, temve\u010D uresni\u010Duje na\u010Delo 'ne \u0161kodovati' s prepre\u010Devanjem nesmiselne agonije.\\n\\nNina Beyokol (Pirati) in drugi podporniki ostro zavra\u010Dajo vme\u0161avanje RKC v kampanjo, sklicujo\u010D se na ustavno lo\u010Denost cerkve in dr\u017Eave. Poudarjajo, da zakon vsebuje stroge varovalke, vklju\u010Dno z ve\u010Dstopenjskim preverjanjem neodvisnih strokovnjakov in komisije, ter zagotavlja pravico do ugovora vesti za zdravstveno osebje. Podporniki izpostavljajo tudi rezultate posvetovalnega referenduma, kjer je ve\u010Dina volivcev podprla tak\u0161no ureditev, in trdijo, da legalizacija v tujini (npr. v dr\u017Eavah z visoko razvito paliativo) dejansko izbolj\u0161uje celostno oskrbo umirajo\u010Dih.\"},\"themes\":{\"splosno\":[{\"naslov\":\"Enoten odpor zdravni\u0161kih organizacij in stroke proti zakonu o evtanaziji\",\"povzetek\":\"Klju\u010Dne slovenske zdravni\u0161ke organizacije in strokovnjaki opozarjajo na eti\u010Dni prelom, tveganja zlorab ter poseg v avtonomijo poklica, ki ga prina\u0161a predlagani zakon.\",\"highlights\":[\"Zdravni\u0161ke organizacije soglasno nasprotujejo zakonu, saj ta vna\u0161a eti\u010Dni prelom s temeljnimi na\u010Deli medicine.\",\"Stroka opozarja, da ocenjevanje trpljenja ni medicinski termin in da zakon sili zdravnike v vlogo izvr\u0161evalcev asistence pri samomoru.\",\"Zdravniki namesto pomo\u010Di pri kon\u010Danju \u017Eivljenja zahtevajo sistemsko ureditev paliativne in dolgotrajne oskrbe.\",\"Alojz Ihan izpostavlja, da vklju\u010Ditev asistence pri samomoru med redne zdravstvene storitve grobo posega v strokovno avtonomijo.\"],\"ids\":[\"14.pdf\",\"20.pdf\",\"70.pdf\",\"87.pdf\",\"92.pdf\",\"94.pdf\",\"110.pdf\"],\"mediji\":[\"zdravniskazbornica.si\",\"n1info.si\",\"Delo\",\"druzina.si\",\"delo.si\",\"delo.si\",\"moja-dolenjska.si\"]},{\"naslov\":\"Polemike o vme\u0161avanju Katoli\u0161ke cerkve v referendumsko kampanjo\",\"povzetek\":\"Zagovorniki zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja o\u010Ditajo Katoli\u0161ki cerkvi nedopustno politi\u010Dno agitacijo in kr\u0161enje ustavnih na\u010Del lo\u010Denosti cerkve od dr\u017Eave.\",\"highlights\":[\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica je Nad\u0161kofijo Ljubljana prijavilo in\u0161pektoratu zaradi domnevnih kr\u0161itev zakona o kampanji.\",\"Sociolog Marjan Smrke ocenjuje mobilizacijo vernikov z verskimi simboli in stra\u0161enjem kot problemati\u010Dno.\",\"Cerkev o\u010Ditke zavra\u010Da s trditvijo, da le izpolnjuje svoje poslanstvo obrambe \u017Eivljenja od spo\u010Detja do naravne smrti.\",\"Duhovnik Martin Golob in drugi verski predstavniki so javno pozvali k zavrnitvi zakona, kar je spro\u017Eilo ostre odzive stranke Pirati.\"],\"ids\":[\"43.pdf\",\"44.pdf\",\"65.pdf\",\"68.pdf\",\"72.pdf\",\"96.pdf\",\"97.pdf\"],\"mediji\":[\"slovenskenovice.si\",\"slovenskenovice.si\",\"Delo\",\"Delo\",\"Dnevnik\",\"delo.si\",\"delo.si\"]},{\"naslov\":\"Politi\u010Dna mobilizacija opozicije in civilne dru\u017Ebe za zavrnitev zakona\",\"povzetek\":\"Stranka SDS in razli\u010Dna dru\u0161tva krepijo kampanjo proti zakonu, pri \u010Demer izpostavljajo nevarnost 'spolzkega klanca' in pozivajo k doseganju referendumskega kvoruma.\",\"highlights\":[\"Janez Jan\u0161a in SDS pozivata volivce, naj 23. novembra glasujejo proti zakonu, ki mu nasprotuje tudi stroka.\",\"Metka Zevnik in Ale\u0161 Primc opozarjata na neprimerne primerjave med ljudmi in \u017Eivalmi ter vle\u010Deta vzporednice z zgodovinskimi programi evtanazije.\",\"Tednik Demokracija poudarja, da je za zavrnitev zakona potreben kvorum 339.205 glasov proti.\",\"Nasprotniki svarijo pred izku\u0161njami iz tujine, kjer se evtanazija izvaja tudi zaradi rev\u0161\u010Dine ali osamljenosti.\"],\"ids\":[\"16.pdf\",\"28.pdf\",\"33.pdf\",\"34.pdf\",\"56.pdf\",\"98.pdf\",\"100.pdf\",\"102.pdf\",\"104.pdf\"],\"mediji\":[\"sta.si\",\"nova24tv.si\",\"nova24tv.si\",\"nova24tv.si\",\"notranjska.si\",\"demokracija.si\",\"demokracija.si\",\"demokracija.si\",\"iskreni.net\"]},{\"naslov\":\"Eti\u010Dni in filozofski vidiki dostojanstva ob koncu \u017Eivljenja\",\"povzetek\":\"Razprave se osredoto\u010Dajo na vpra\u0161anje, ali je pomo\u010D pri kon\u010Danju \u017Eivljenja izraz svobodne volje ali dru\u017Ebenega neuspeha pri skrbi za naj\u0161ibkej\u0161e.\",\"highlights\":[\"Moralni teolog Ivan \u0160tuhec trdi, da zakon spodkopava temelje dru\u017Ebene morale in sili dr\u017Eavljane v financiranje evtanazije.\",\"Duhovnik Martin Golob poudarja, da vrednost \u010Dloveka ni v njegovi uporabnosti, temve\u010D v samem obstoju in ljubezni.\",\"Osebne zgodbe iz tujine opozarjajo, da je odlo\u010Ditev za smrt pogosto posledica pomanjkanja bli\u017Eine in psiholo\u0161ke podpore.\",\"Zagovorniki v Mladini poudarijo pravico do avtonomije in dostojne smrti brez nepotrebnega trpljenja.\"],\"ids\":[\"25.pdf\",\"53.pdf\",\"73.pdf\",\"75.pdf\",\"81.pdf\"],\"mediji\":[\"nova24tv.si\",\"nadlani.si\",\"Mladina\",\"Mladina\",\"Novice - slovenski tednik na Koro\u0161kem\"]},{\"naslov\":\"Kritika vladnih prioritet: Kultura, UI in zdravstvena kriza\",\"povzetek\":\"Mediji blizu opozicije kritizirajo vladne projekte, kot sta nov zavod za ples in platforma za UI, ter jih postavljajo v kontrast z nere\u0161enimi te\u017Eavami v zdravstvu.\",\"highlights\":[\"Ustanovitev javnega zavoda za sodobni ples je tar\u010Da kritik zaradi porabe \u0161tirih milijonov evrov v \u010Dasu gospodarske stiske.\",\"Vladni projekt nacionalne platforme za umetno inteligenco kritiki ozna\u010Dujejo za drag projekt z nevarnostjo ideolo\u0161ke indoktrinacije.\",\"SDS predlaga paket \u0161estih ukrepov za re\u0161evanje zdravstva, vklju\u010Dno z lo\u010Denim pla\u010Dnim stebrom in statusom svobodnega zdravnika.\",\"Kritika ministrstva za kulturo zaradi organizacije Pre\u0161ernovega dne v Islamskem kulturnem centru.\"],\"ids\":[\"23.pdf\",\"27.pdf\",\"32.pdf\",\"45.pdf\"],\"mediji\":[\"nova24tv.si\",\"nova24tv.si\",\"nova24tv.si\",\"demokracija.si\"]},{\"naslov\":\"Tehni\u010Dne informacije in napovedi pred referendumom\",\"povzetek\":\"Objave vklju\u010Dujejo uradna obvestila o poteku pred\u010Dasnega glasovanja, vsebino predlaganega zakona in napovedi medijskih analiz.\",\"highlights\":[\"Pred\u010Dasno glasovanje o zakonu bo potekalo od 18. do 20. novembra na lokacijah v Ljubljani.\",\"Zakon predvideva pravico do pomo\u010Di pri kon\u010Danju \u017Eivljenja za polnoletne osebe z neozdravljivo boleznijo in neznosnim trpljenjem.\",\"V Novem mestu bo 18. novembra potekal strokovni pogovorni ve\u010Der proti pomo\u010Di pri samomoru.\",\"STA in Ve\u010Der napovedujeta poglobljene analize kampanje in politi\u010Dnih razmerij pred referendumom.\"],\"ids\":[\"47.pdf\",\"67.pdf\",\"82.pdf\",\"89.pdf\",\"108.pdf\"],\"mediji\":[\"gov.si\",\"Delo\",\"sta.si\",\"vecer.com\",\"moja-dolenjska.si\"]}],\"nasprotniki\":[{\"naslov\":\"Enoten upor zdravni\u0161kih organizacij in eti\u010Dni prelom v medicini\",\"povzetek\":\"Klju\u010Dne slovenske zdravni\u0161ke organizacije in posamezni strokovnjaki opozarjajo, da zakon sili zdravnike v vlogo izvajalcev usmrtitev, kar ru\u0161i tiso\u010Dletno medicinsko etiko in zaupanje bolnikov.\",\"highlights\":[\"Zdravni\u0161ke organizacije zakon ozna\u010Dujejo za nevaren dru\u017Ebeni eksperiment, ki kr\u0161i temeljno na\u010Delo 'ne \u0161koduj'.\",\"Stroka opozarja, da zakon uvaja pomo\u010D pri samomoru na na\u010Din, ki v svetu ne obstaja, saj sili osebje k neposredni prisotnosti pri dejanju.\",\"Zdravniki poudarjajo, da je njihovo poslanstvo zdravljenje in ohranjanje \u017Eivljenja, ne pa 'morjenje ljudi' po ukazu dr\u017Eave.\",\"Opozarjajo na neizogibno mno\u017Ei\u010Dno uveljavljanje ugovora vesti, kar bo dodatno ohromilo \u017Ee tako podhranjen zdravstveni sistem.\"],\"ids\":[\"14.pdf\",\"20.pdf\",\"70.pdf\",\"87.pdf\",\"92.pdf\",\"110.pdf\"],\"mediji\":[\"zdravniskazbornica.si\",\"n1info.si\",\"Delo\",\"druzina.si\",\"delo.si\",\"moja-dolenjska.si\"]},{\"naslov\":\"Verski in moralni argumenti proti 'kulturi smrti'\",\"povzetek\":\"Predstavniki Katoli\u0161ke cerkve in drugih verskih skupnosti zakon ostro zavra\u010Dajo kot poseg v bo\u017Ejo domeno nad \u017Eivljenjem in ga ozna\u010Dujejo za 'legalizacijo ubijanja'.\",\"highlights\":[\"Duhovnik Martin Golob in vrh RKC poudarjata, da je le Bog gospodar \u017Eivljenja in smrti, glasovanje za zakon pa ozna\u010Dujejo za te\u017Eak greh.\",\"Nad\u0161kof Stanislav Zore je v pastirskih pismih uporabil ekstremne primerjave z nacisti\u010Dnimi programi evtanazije ('Gnadentod').\",\"Cerkev uporablja svojo organizacijsko mre\u017Eo in verske simbole za mobilizacijo vernikov k glasovanju 'proti' na referendumu.\",\"Poudarjajo kr\u0161\u010Dansko vrednoto trpljenja kot prilo\u017Enosti za osebnostno rast in o\u010Di\u0161\u010Denje pred smrtjo.\"],\"ids\":[\"43.pdf\",\"53.pdf\",\"68.pdf\",\"72.pdf\",\"73.pdf\"],\"mediji\":[\"slovenskenovice.si\",\"nadlani.si\",\"Delo\",\"Dnevnik\",\"Mladina\"]},{\"naslov\":\"Politi\u010Dna kritika zakona kot orodja 'Golobove koalicije'\",\"povzetek\":\"Opozicija s stranko SDS na \u010Delu zakon interpretira kot ideolo\u0161ki projekt leve vlade, ki naj bi slu\u017Eil prikrivanju neuspehov v zdravstvu in dolgotrajni oskrbi.\",\"highlights\":[\"Janez Jan\u0161a in SDS opozarjajo, da zakon kr\u0161i 17. \u010Dlen ustave o nedotakljivosti \u010Dlovekovega \u017Eivljenja.\",\"Kritiki trdijo, da vlada ponuja smrt kot cenej\u0161o alternativo, ker ni sposobna urediti paliativne oskrbe in domov za starej\u0161e.\",\"Glasovanje proti zakonu se v medijih, kot je Demokracija, promovira tudi kot glas proti '\u0161kodljivi Golobovi vladi'.\",\"Izpostavljajo se finan\u010Dni motivi dr\u017Eave, \u010De\u0161 da je evtanazija '\u0161paranje' na ra\u010Dun najranljivej\u0161ih dr\u017Eavljanov.\"],\"ids\":[\"16.pdf\",\"25.pdf\",\"33.pdf\",\"45.pdf\",\"102.pdf\"],\"mediji\":[\"sta.si\",\"nova24tv.si\",\"nova24tv.si\",\"demokracija.si\",\"demokracija.si\"]},{\"naslov\":\"Opozorila pred zlorabami in 'spolzkim klancem'\",\"povzetek\":\"Nasprotniki svarijo pred nejasnimi definicijami trpljenja in izku\u0161njami iz tujine, kjer naj bi evtanazija postala sredstvo za re\u0161evanje socialnih stisk in rev\u0161\u010Dine.\",\"highlights\":[\"Dru\u0161tvo Usidrani in drugi kritiki opozarjajo na primere iz Kanade in Belgije, kjer se evtanazija izvaja zaradi osamljenosti ali pomanjkanja sredstev.\",\"Izpostavljajo tveganje 'evtanazijskega mobinga', kjer bi se starej\u0161i po\u010Dutili kot breme svojcem in se zato odlo\u010Dili za smrt.\",\"Kritizirajo pomanjkanje nadzora nad komisijo, ki bo odlo\u010Dala o smrti, in nejasno definicijo 'neznosnega trpljenja'.\",\"Opozarjajo na tehni\u010Dne vidike usmrtitve, ki naj bi bili v praksi bole\u010Di in travmati\u010Dni za vpletene.\"],\"ids\":[\"28.pdf\",\"56.pdf\",\"67.pdf\",\"81.pdf\",\"104.pdf\"],\"mediji\":[\"nova24tv.si\",\"notranjska.si\",\"Delo\",\"Novice - slovenski tednik na Koro\u0161kem\",\"iskreni.net\"]},{\"naslov\":\"Sistemske luknje in pravna nesigurnost zakona\",\"povzetek\":\"Pravni in medicinski strokovnjaki opozarjajo na nevarne dolo\u010Dbe zakona, ki bi lahko vodile do nekaznovanih zlorab in ponarejanja uradnih dokumentov.\",\"highlights\":[\"Zakon naj bi od zdravnikov zahteval navajanje neresni\u010Dnih vzrokov smrti v uradnih poro\u010Dilih po izvedbi postopka.\",\"Izklju\u010Ditev kazenske in od\u0161kodninske odgovornosti za sodelujo\u010De v postopku po mnenju kritikov odpira vrata zlorabam.\",\"Opozarjajo, da zakon ne dolo\u010Da postopkov v primeru zapletov pri samousmrtitvi, kot so kr\u010Di ali bruhanje.\",\"Dr. Zvonka Zupani\u010D Slavec poudarja, da je bil zakon pripravljen v 'medijski ti\u0161ini' in brez sodelovanja zdravni\u0161kih organizacij.\"],\"ids\":[\"22.pdf\",\"23.pdf\",\"27.pdf\",\"32.pdf\",\"98.pdf\",\"100.pdf\"],\"mediji\":[\"nova24tv.si\",\"nova24tv.si\",\"nova24tv.si\",\"nova24tv.si\",\"demokracija.si\",\"demokracija.si\"]}],\"podporniki\":[{\"naslov\":\"Pravica do dostojanstvenega konca in osebna avtonomija\",\"povzetek\":\"Podporniki zakona utemeljujejo svoja stali\u0161\u010Da na pravici posameznika do samoodlo\u010Dbe, dostojanstvene smrti in prepre\u010Devanja neznosnega trpljenja.\",\"highlights\":[\"Zagovorniki poudarjajo, da je odlo\u010Ditev o koncu \u017Eivljenja povsem osebna in ne bi smela biti v domeni verskih ali zdravni\u0161kih zdru\u017Eenj.\",\"Pravica do mirnega, nadzorovanega in dostojanstvenega konca je izpostavljena kot temeljna humanisti\u010Dna vrednota.\",\"Podporniki trdijo, da pomo\u010D pri kon\u010Danju \u017Eivljenja uresni\u010Duje bistvo zdravni\u0161kega poklica v smislu prepre\u010Devanja trpljenja brez smisla.\",\"Zakon je predstavljen kot izraz svobode posameznika in napredka v okviru modernega progresivizma.\"],\"ids\":[\"16.pdf\",\"25.pdf\",\"65.pdf\",\"67.pdf\",\"75.pdf\"],\"mediji\":[\"sta.si\",\"nova24tv.si\",\"Delo\",\"Delo\",\"Mladina\"]},{\"naslov\":\"Kritika vme\u0161avanja Rimskokatoli\u0161ke cerkve v referendumsko kampanjo\",\"povzetek\":\"Zagovorniki zakona in civilna dru\u017Eba opozarjajo na domnevno neprimerno in ustavno sporno vklju\u010Devanje cerkve v politi\u010Dno odlo\u010Danje.\",\"highlights\":[\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica je Nad\u0161kofijo Ljubljana prijavilo in\u0161pektoratu zaradi kr\u0161itev zakona o referendumski kampanji.\",\"Podporniki izpostavljajo ustavno lo\u010Denost cerkve in dr\u017Eave ter zahtevajo, da verske skupnosti ne vsiljujejo svoje volje vsem dr\u017Eavljanom.\",\"Cerkev je obto\u017Eena zlorabe verskih simbolov, stra\u0161enja vernikov z 'grehom' in izvajanja nepo\u0161tene mobilizacije.\",\"Zagovorniki opozarjajo, da cerkev s svojimi aktivnostmi prestopa zakonske in ustavne okvire dovoljenega politi\u010Dnega delovanja.\"],\"ids\":[\"43.pdf\",\"44.pdf\",\"68.pdf\",\"72.pdf\",\"96.pdf\",\"97.pdf\"],\"mediji\":[\"slovenskenovice.si\",\"slovenskenovice.si\",\"Delo\",\"Dnevnik\",\"delo.si\",\"delo.si\"]},{\"naslov\":\"Argumentacija o humanosti in primerjava s trpljenjem \u017Eivali\",\"povzetek\":\"Del podpornikov uporablja primerjavo z usmrtitvijo trpe\u010Dih \u017Eivali kot argument za humano prekinitev \u010Dlove\u0161kega trpljenja.\",\"highlights\":[\"Nina Beyokol izpostavlja, da ljudje ne pustijo trpeti hi\u0161nih ljubljen\u010Dkov, zato bi morali enako so\u010Dutje pokazati do trpe\u010Dih ljudi.\",\"Zagovorniki trdijo, da med trpljenjem \u010Dloveka in \u017Eivali v dolo\u010Denih fazah neozdravljive bolezni ni prakti\u010Dne razlike.\",\"Argumentacija temelji na vpra\u0161anju, zakaj bi od bli\u017Enjih zahtevali opazovanje trpljenja, \u010De si oseba \u017Eeli pomo\u010Di.\"],\"ids\":[\"28.pdf\",\"34.pdf\",\"25.pdf\"],\"mediji\":[\"nova24tv.si\",\"nova24tv.si\",\"nova24tv.si\"]},{\"naslov\":\"Vloga dru\u0161tva Srebrna nit in koalicije pri pripravi zakona\",\"povzetek\":\"Dru\u0161tvo Srebrna nit in vladajo\u010Da koalicija sta klju\u010Dna akterja, ki sta pripravila zakonsko podlago na podlagi volje volivcev.\",\"highlights\":[\"Zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja (ZPPK\u017D) je pripravilo zdru\u017Eenje Srebrna nit.\",\"Podporniki se sklicujejo na rezultate posvetovalnega referenduma, kjer je ve\u010Dina volivcev podprla tak\u0161no ureditev.\",\"Zagovorniki trdijo, da je zakonodaja finan\u010Dno vzdr\u017Enej\u0161a od dolgotrajne oskrbe in prina\u0161a novo nujno pravico v slovenski sistem.\",\"V kampanjo je vklju\u010Denih 33 organizatorjev, ki podpirajo uveljavitev zakona.\"],\"ids\":[\"98.pdf\",\"100.pdf\",\"102.pdf\",\"20.pdf\",\"67.pdf\"],\"mediji\":[\"demokracija.si\",\"demokracija.si\",\"demokracija.si\",\"n1info.si\",\"Delo\"]},{\"naslov\":\"Volja volivcev in zahteva po novi pravici do izbire\",\"povzetek\":\"Analize poudarjajo, da slovenski volivci zakon razumejo kot pridobitev nove osebne pravice, ki bi jo lahko uporabili v stiski.\",\"highlights\":[\"Volivci si \u017Eelijo imeti v rokah pravico do izbire, ne glede na pomisleke medicinske stroke.\",\"Podpora zakonu temelji na misli na novo pravico do asistirane samousmrtitve v dolo\u010Denih okoli\u0161\u010Dinah.\",\"Javnomnenjske raziskave ka\u017Eejo visoko podporo med dr\u017Eavljani, vklju\u010Dno z verniki, kljub nasprotovanju institucij.\"],\"ids\":[\"70.pdf\",\"92.pdf\",\"94.pdf\",\"75.pdf\"],\"mediji\":[\"Delo\",\"delo.si\",\"delo.si\",\"Mladina\"]},{\"naslov\":\"Tehni\u010Dne informacije o izvedbi referenduma\",\"povzetek\":\"Uradni organi in mediji podajajo nevtralne informacije o postopkih pred\u010Dasnega glasovanja in referendumskih pravilih.\",\"highlights\":[\"Pred\u010Dasno glasovanje o zakonu poteka med 18. in 20. novembrom na lokacijah Upravne enote Ljubljana.\",\"Za zavrnitev zakona na referendumu je potreben kvorum 339.205 glasov proti.\",\"Mediji napovedujejo analize pri\u010Dakovanega razpleta referenduma v okviru \u0161ir\u0161ega politi\u010Dnega dogajanja.\"],\"ids\":[\"47.pdf\",\"89.pdf\",\"98.pdf\"],\"mediji\":[\"gov.si\",\"vecer.com\",\"demokracija.si\"]}]},\"articles\":[{\"naslov\":\"Slovenske zdravni\u0161ke organizacije: \u010Ce \u017Eelimo pomagati, potrebujemo Zakon o\",\"medij\":\"zdravniskazbornica.si\",\"datum\":\"12. 11. 2025\",\"avtor\":null,\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Predstavniki Komisije Republike Slovenije za medicinsko etiko, Slovenske medicinske akademije, Zdravni\u0161ke zbornice Slovenije, Slovenskega zdravni\u0161kega dru\u0161tva, Katedre za medicinsko etiko Medicinske fakultete Univerze ob podpori Svetovnega zdravni\u0161kega zdru\u017Eenja, zdru\u017Eenj za paliativno oskrbo in hospicev so danes na skupni novinarski\",\"url\":\"https:\/\/www.zdravniskazbornica.si\/informacije-publikacije-in-analize\/obvestila\/2025\/11\/12\/slovenske-zdravni\u0161ke-organizacije-\u010De-\u017Eelimo-pomagati-potrebujemo-zakon-o-paliativni-oskrbi-in-ne-o-pomo\u010Di-pri-prostovoljnem-kon\u010Danju-\u017Eivljenja\",\"id\":\"14.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Predstavniki klju\u010Dnih slovenskih zdravni\u0161kih organizacij so na skupni novinarski konferenci soglasno izrazili nasprotovanje predlaganemu Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Zdravni\u0161ke organizacije opozarjajo, da bi zakon pove\u010Dal tveganje za zlorabe in poslab\u0161al dostopnost paliativne oskrbe.\",\"Stroka poudarja, da zakon vna\u0161a eti\u010Dni prelom s temeljnimi na\u010Deli medicine in ogro\u017Ea zaupanje med bolnikom in zdravnikom.\",\"Namesto pomo\u010Di pri samomoru zdravniki pozivajo k sistemski ureditvi dolgotrajne oskrbe in okrepitvi paliativne pomo\u010Di.\"]},\"nasprotniki\":{\"povzetek\":\"Slovenske zdravni\u0161ke organizacije, vklju\u010Dno z Zdravni\u0161ko zbornico, Komisijo za medicinsko etiko in Zdru\u017Eenjem psihiatrov, zakon ozna\u010Dujejo za nevaren dru\u017Ebeni eksperiment, ki kr\u0161i na\u010Delo 'ne \u0161koduj'.\",\"highlights\":[\"\\\"Zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja po njihovem prepri\u010Danju ni izraz so\u010Dutja, temve\u010D nevaren dru\u017Ebeni eksperiment.\\\"\",\"\\\"Zakon prihaja v \u010Dasu, ko 150 tiso\u010D ljudi v Sloveniji nima osebnega zdravnika, paliativna oskrba je podhranjena, dolgotrajna oskrba starej\u0161ih pa neurejena.\\\"\",\"\\\"Neznosno trpljenje ni nikjer definirano. Komisija, ki o tem odlo\u010Da, ne pozna bolnika, kar odpira vrata zlorabam.\\\"\",\"\\\"Zakon ne dolo\u010Da, kaj mora zdravnik ali medicinska sestra storiti, \u010De pride do zapletov, do kr\u010Dev, bruhanja ali epilepti\u010Dnega napada.\\\"\",\"\\\"Z legalizacijo pomo\u010Di pri samomoru bomo uti\u0161ali ta klic [po pomo\u010Di], kar bo nepopravljiva \u0161koda za dru\u017Ebo.\\\"\",\"\\\"Ko dru\u017Eba sprejme smrt kot re\u0161itev, za\u010Dne izgubljati spo\u0161tovanje do \u017Eivljenja. Starej\u0161i in ranljivi se lahko za\u010Dnejo po\u010Dutiti kot breme.\\\"\",\"\\\"Zakon vna\u0161a mo\u017Enost, da se \u017Eivljenje posameznika ob sodelovanju zdravnikov ovrednoti s prostovoljnim kon\u010Danjem oziroma s samousmrtitvijo.\\\"\",\"\\\"Vloga zdravnika je, da pomaga trpe\u010Dim in re\u0161uje \u017Eivljenja. Novi zakon pa zdravnika sili, da dela v nasprotju s tem poslanstvom.\\\"\",\"\\\"Zdravniki bomo pogosto uveljavljali ugovor vesti, kar bo dodatno obremenilo sistem, ki \u017Ee zdaj komaj deluje.\\\"\",\"\\\"Opozarjamo na pove\u010Dano tveganje t. i. 'evtanazijskega mobinga', na katerega opozarjajo zdravniki v tistih nekaj dr\u017Eavah, kjer je evtanazija \u017Ee vklju\u010Dena v nacionalno zakonodajo.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Demokracija o zakonu o prostovoljnem kon\u010Danju \u017Eivljenja (13. 11.)\",\"medij\":\"sta.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"mo\/spc\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Metod Berlec v komentarju Za kulturo \u017Eivljenja, proti levi\u010Darski kulturi smrti pi\u0161e o zakonu o prostovoljnem kon\u010Danju \u017Eivljenja. Njegovi zagovorniki ga predstavljajo kot izraz svobode posameznika, a po njegovem mnenju gre v resnici za nevarno relativizacijo temeljne ustavne vrednote - nedotakljivosti \u010Dlovekovega \u017Eivljenja.\",\"url\":\"https:\/\/www.sta.si\/3487945\",\"id\":\"16.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Metod Berlec v svojem komentarju ostro nasprotuje zakonu o prostovoljnem kon\u010Danju \u017Eivljenja in poziva k glasovanju proti njemu na prihajajo\u010Dem referendumu.\",\"highlights\":[\"Avtor trdi, da zakon predstavlja nevarno relativizacijo ustavne vrednote nedotakljivosti \u010Dlovekovega \u017Eivljenja.\",\"Zakon ozna\u010Duje kot asistiranje pri samomoru, ki bi pomenilo aktivno dr\u017Eavno legitimacijo posega v \u017Eivljenje.\",\"Glasovanje proti zakonu avtor povezuje z nasprotovanjem trenutni vladi in koaliciji, ki naj bi Slovenijo vodila v propad.\"]},\"nasprotniki\":{\"povzetek\":\"Metod Berlec uporablja ideolo\u0161ko in politi\u010Dno retoriko, s katero zakon ozna\u010Duje za 'kulturo smrti' ter poziva k obrambi kr\u0161\u010Danskih civilizacijskih temeljev.\",\"highlights\":[\"\\\"Zakon, ki uzakonja pomo\u010D pri kon\u010Danju \u017Eivljenja, se pravi asistiranje pri samomoru, pomeni, da bi slovenska dr\u017Eava aktivno legitimirala poseg v \u017Eivljenje kot nekaj dopustnega.\\\"\",\"\\\"Gre v resnici za nevarno relativizacijo temeljne ustavne vrednote - nedotakljivosti \u010Dlovekovega \u017Eivljenja.\\\"\",\"\\\"Zato bo treba prihodnjo nedeljo, 23. novembra 2025, nujno glasovati proti temu spornemu zakonu.\\\"\",\"\\\"S tem bomo glasovali tudi proti \u0161kodljivi Golobovi vladi in proti neosocialisti\u010Dni koaliciji Gibanja Svoboda, SD in Levice, ki Slovenijo pelje v napa\u010Dno smer - v smer regresije in propada.\\\"\",\"\\\"Glas PROTI zakonu je glas za kulturo \u017Eivljenja, za spo\u0161tovanje ustave, za narod, za pozitivno slovensko prihodnost.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona so v \u010Dlanku omenjeni le posredno preko avtorjeve kritike njihovega argumenta o osebni svobodi.\",\"highlights\":[\"\\\"Njegovi zagovorniki ga predstavljajo kot izraz svobode posameznika\\\"\"]}}},{\"naslov\":\"\u0160okantno vedenje negovalke v Celju: Pristojni ukrepali prepozno?\",\"medij\":\"informer.si\",\"datum\":\"13. 11. 2025\",\"avtor\":null,\"oznaka\":[\"SREBRNA NIT\"],\"intro\":\"V domu starej\u0161ih v Celju je pri\u0161lo do pretresljivega incidenta, kjer je negovalka neprimerno ravnala z ve\u010D oskrbovanci. Posnetki, ki so se pojavili na dru\u017Ebenih omre\u017Ejih, razkrivajo nedostojno vedenje negovalke do nepokretne \u017Eenske in oslabljenega mo\u0161kega.\",\"url\":\"https:\/\/informer.si\/sokantno-vedenje-negovalke-v-celju-pristojni-ukrepali-prepozno\/\",\"id\":\"17.pdf\",\"contents\":null},{\"naslov\":\"\\\"Ocenjevanje trpljenja ni strokovni termin v medicini\\\"\",\"medij\":\"n1info.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"U. M.\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V okviru javne razprave o pravici do pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja smo prejeli pismo z naslovom \\\"Premislek pred referendumom\\\", pod katerega so se podpisale tri zdravnice razli\u010Dnih praks: Maja Klarendi\u0107, Sanja Zupani\u010D Mali in dr. Maja Ebert Moltara. Poudarjajo, da ne \u017Eelijo moralizirati, a ker zakon o pomo\u010Di pri prostovoljnem\",\"url\":\"https:\/\/n1info.si\/novice\/slovenija\/ocenjevanje-trpljenja-ni-strokovni-termin-v-medicini\/\",\"id\":\"20.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Tri zdravnice so v javni razpravi o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja (ZPPK\u017D) izpostavile devet to\u010Dk, ki so po njihovem mnenju sistemsko in eti\u010Dno problemati\u010Dne.\",\"highlights\":[\"Zdravnice Maja Klarendi\u0107, Sanja Zupani\u010D Mali in dr. Maja Ebert Moltara opozarjajo, da slovenski predlog zakona uvaja pomo\u010D pri samomoru na svetovno neobstoje\u010D na\u010Din.\",\"Avtorice pisma poudarjajo, da bi morala biti prednostna naloga ureditev paliativne oskrbe in dostopa do osebnih zdravnikov, ne pa uvajanje nove pravice v neurejen sistem.\",\"Kritika leti tudi na dolo\u010Dbo, ki od zdravnikov zahteva navajanje neresni\u010Dnih vzrokov smrti v uradnih poro\u010Dilih po izvedbi postopka.\"]},\"nasprotniki\":{\"povzetek\":\"Zdravnice Maja Klarendi\u0107, Sanja Zupani\u010D Mali in dr. Maja Ebert Moltara v pismu 'Premislek pred referendumom' argumentirano nasprotujejo trenutni ureditvi ZPPK\u017D zaradi sistemskih pomanjkljivosti in eti\u010Dnih dilem.\",\"highlights\":[\"\\\"Slovenski zakon uvaja pomo\u010D pri samomoru na svetovno neobstoje\u010D na\u010Din, saj bosta morala biti le\u010De\u010Di zdravnik ali medicinska sestra zraven do konca.\\\"\",\"\\\"Zakon s to dolo\u010Dbo uvaja neenakosti pri bolnikih, saj tudi drugih umirajo\u010Dih ne moremo spremljati ves \u010Das umiranja.\\\"\",\"\\\"Nikakr\u0161nega zagotovila ni, da se z novimi zakonskimi spremembami \u010Dez \u010Das ne bi odvzela tudi pravica do ugovora vesti.\\\"\",\"\\\"Paliativna dejavnost se dobro razvija samo, \u010De je imela dr\u017Eava, ki je sprejela zakon o PPK\u017D, \u017Ee pred tem zelo dobro oceno na ELQR lestvici.\\\"\",\"\\\"Nova pravica bo v sistem vnesla nove nepravi\u010Dnosti in neenakosti.\\\"\",\"\\\"Z zakonom se zdravnika sili v navedbo la\u017Enih podatkov,\\\" ker se neposredni vzrok smrti ne upo\u0161teva v poro\u010Dilu.\",\"\\\"Izklju\u010Ditev kazenske, od\u0161kodninske in disciplinske odgovornosti za vse, ki sodelujejo v postopkih, odpira vrata zlorabam.\\\"\",\"\\\"Ocenjevanje trpljenja ni strokovni termin v medicini, temve\u010D socialni, duhovni, telesni in du\u0161evni.\\\"\",\"\\\"Sedanja opredelitev omogo\u010Da PPK\u017D tudi ljudem, ki bi lahko \u017Eiveli \u0161e desetletja.\\\"\",\"\\\"Zaradi ve\u010Dje avtonomije posameznikov, ki si \u017Eelijo PPK\u017D, pomembno posegamo v avtonomijo in \u010Dustvovanje drugih posameznikov in njim povzro\u010Damo nepotrebno trpljenje, stres in travmo.\\\"\"]},\"podporniki\":{\"povzetek\":\"\u010Clanek omenja neimenovane zagovornike pravice do pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki trdijo, da tak\u0161na zakonodaja izbolj\u0161uje paliativno oskrbo.\",\"highlights\":[\"Zagovorniki trdijo, \\\"da se v dr\u017Eavah, kjer obstajajo mo\u017Enosti pomo\u010Di pri kon\u010Devanju \u017Eivljenja, paliativna oskrba \u0161e izbolj\u0161a.\\\"\",\"Zakon prina\u0161a novo pravico do pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja (ZPPK\u017D).\"]}}},{\"naslov\":\"Je v Ljubljani z no\u017Eem mesaril migrant?\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"Marko Pu\u0161\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Na Bavarskem dvoru v Ljubljani je neznani osumljenec po do zdaj znanih podatkih z ostrim predmetom huje po\u0161kodoval voznika avtobusa in po dogodku pobegnil. Po podatkih iz socialnih omre\u017Eij naj bi bil storilec migrant. V popoldanskih urah se je na avtobusu Ljubljanskega potni\u0161kega prometa dogajala prava drama. Pri\u010De so za STA\",\"url\":\"https:\/\/nova24tv.si\/je-z-nozem-mesaril-ilegalec\/\",\"id\":\"22.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek poro\u010Da o nasilnem napadu na voznika avtobusa v Ljubljani, pri \u010Demer se sklicuje na neuradne informacije s socialnih omre\u017Eij, da naj bi bil storilec migrant.\",\"highlights\":[\"Neznani osumljenec je na Bavarskem dvoru z ostrim predmetom huje po\u0161kodoval voznika avtobusa Ljubljanskega potni\u0161kega prometa.\",\"Policija poziva k previdnosti, saj je storilec, opisan kot mo\u0161ki s svetlimi lasmi in brado v rde\u010Di jakni, \u0161e vedno na begu.\",\"Avtor \u010Dlanka v naslovu in besedilu izpostavlja ugibanja, da naj bi bil napadalec migrant.\"]},\"nasprotniki\":{\"povzetek\":\"\u010Clanek vklju\u010Duje povezavo do vsebine, ki opozarja na domnevne pomanjkljivosti oziroma nevarnosti v zakonodaji o evtanaziji.\",\"highlights\":[\"\\\"Luknje v zakonu o evtanaziji, v katere lahko pade vsak\\\"\"]},\"podporniki\":null}},{\"naslov\":\"\u0160e ple\u0161ete? Zahvaljujo\u010D stranki Levica boste po novem financirali zavod za sodobni\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"A.H.\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"V \u010Dasu, ko dru\u017Eine komaj shajajo, bolni otroci \u010Dakajo na donacije, cene osnovnih dobrin pa divje rastejo, se stranka Levica odlo\u010Di za ustanovitev javnega zavoda za sodobni ples \u2013 \u0161e enega nepotrebnega sesalca za davkopla\u010Devalski denar.\",\"url\":\"https:\/\/nova24tv.si\/se-plesete-zahvaljujoc-stranki-levica-boste-po-novem-financirali-zavod-za-sodobni-ples\/\",\"id\":\"23.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek ostro kritizira odlo\u010Ditev ministrice za kulturo Aste Vre\u010Dko in stranke Levica o ustanovitvi novega javnega zavoda za sodobni ples v \u010Dasu gospodarske in socialne stiske.\",\"highlights\":[\"Novi javni zavod za razvoj sodobne plesne umetnosti bo v \u0161tirih letih porabil \u0161tiri milijone evrov iz dr\u017Eavnega prora\u010Duna in drugih virov.\",\"Kritiki poudarjajo neskladje med financiranjem ni\u0161nih kulturnih projektov in nere\u0161enimi te\u017Eavami v zdravstvu, stanovanjski politiki ter poplavni obnovi.\",\"Javnost na dru\u017Ebenih omre\u017Ejih izra\u017Ea ogor\u010Denje nad prioritetami vlade, ki jih ozna\u010Dujejo za 'institucionalizirano krajo' davkopla\u010Devalskega denarja.\"]},\"nasprotniki\":{\"povzetek\":\"\u010Clanek v enem izmed podnaslovov in gesel omenja evtanazijo v izrazito negativnem in opozorilnem kontekstu, vendar se vsebina primarno osredoto\u010Da na kritiko kulturnih investicij.\",\"highlights\":[\"\\\"Luknje v zakonu o evtanaziji, v katere lahko pade vsak\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Dr. Ivan \u0160tuhec: Zakaj bi moral kdorkoli sodelovati pri evtanaziji?\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"zgk\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\"],\"intro\":\"Referendum Proti zastrupitvi in zlorabam bolnikov se pribli\u017Euje z nezadr\u017Eno hitrostjo. Tega spremlja vrsta eti\u010Dnih dilem, zato smo pred glasovanjem, ki bo potekalo naslednjo nedeljo, spregovorili z moralnim teologom dr. Ivanom \u0160tuhcem. Ta je predstavil nekaj klju\u010Dnih pomislekov \u2013 med drugim je za na\u0161e bralce obrazlo\u017Eil, kako bi uveljavitev pravice do\",\"url\":\"https:\/\/nova24tv.si\/dr-ivan-stuhec-zakaj-bi-moral-kdorkoli-sodelovati-pri-evtanaziji\/\",\"id\":\"25.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Moralni teolog dr. Ivan \u0160tuhec v intervjuju pred referendumom ostro nasprotuje zakonu o evtanaziji, saj meni, da ta spodkopava temelje zdravni\u0161kega poklica in v moralno sporno dejanje sili celotno dru\u017Ebo.\",\"highlights\":[\"Dr. Ivan \u0160tuhec trdi, da bi uveljavitev evtanazije pomenila, da bi manj\u0161ina zagovornikov diktirala ve\u010Dini zdravni\u0161tva ravnanje, ki je v nasprotju z njihovo moralo.\",\"Avtor izpostavlja problem prisilne participacije zdravstvenega osebja in vseh dr\u017Eavljanov, ki bi postopek financirali prek obveznega zdravstvenega zavarovanja.\",\"V \u010Dlanku so zavrnjeni argumenti o finan\u010Dni vzdr\u017Enosti evtanazije in primerjave med \u010Dlove\u0161kim trpljenjem ter usmrtitvijo \u017Eivali.\"]},\"nasprotniki\":{\"povzetek\":\"Dr. Ivan \u0160tuhec in medij Nova24tv v \u010Dlanku uporabljata retoriko o 'zastrupitvi bolnikov' in 'prisili' za \u0161irjenje dvoma o eti\u010Dnosti in pravni varnosti predlaganega zakona.\",\"highlights\":[\"\\\"Referendum Proti zastrupitvi in zlorabam bolnikov se pribli\u017Euje z nezadr\u017Eno hitrostjo.\\\"\",\"\\\"uveljavitev bi pripeljala do tega, da bi manj\u0161ina zagovornikov evtanazije diktirala ve\u010Dini zdravni\u0161tva, da izvaja nekaj, kar je v nasprotju z njihovo moralo.\\\"\",\"\\\"Gre za globok rez, ki na\u010Denja dolgo tradicijo zdravni\u0161kega poklica.\\\"\",\"\\\"Tu gre prakti\u010Dno za prisilo.\\\"\",\"\\\"Ne moremo pa biti solidarni zato, da bodo ljudje delali samomore, ali pa da jih na drugi svet spravi nekdo drug.\\\"\",\"\\\"Zakon tudi v pravnem pomenu na splozkem terenu, saj bi se lahko na neki to\u010Dki svojca, ki se je odlo\u010Dil za evtanazijo, tistim, ki so mu pri tem pomagali, obto\u017Eili, da so kon\u010Dali njegovo \u017Eivljenje.\\\"\",\"\\\"\u010Ce nekdo postavi na isti nivo \u010Dloveka in \u017Eival, kar se na \u017Ealost danes pogosto dogaja, potem smo \u010Dlove\u0161ko vrsto degradirali na stopnjo ni\u017Eje.\\\"\",\"\\\"kdor to argumentira [finan\u010Dno vzdr\u017Enost], tisti seveda postavlja denar nad \u010Dloveka in to je sprevr\u017Eeno.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki, kot je dru\u0161tvo Srebrna nit, zagovarjajo evtanazijo kot pravico do avtonomije nad lastnim \u017Eivljenjem in jo postavljajo v okvir modernega progresivizma.\",\"highlights\":[\"Zagovorniki vpra\u0161anje evtanazije postavljajo v kontekst modernega kulturnega boja in progresivizma.\",\"Dru\u0161tvo Srebrna nit se v \u010Dlanku omenja kot eden izmed klju\u010Dnih zagovornikov ureditve tega podro\u010Dja.\",\"Zagovorniki argumentirajo, da je evtanazija finan\u010Dno vzdr\u017Enej\u0161a od dolgotrajne oskrbe.\",\"Podporniki trdijo, da med trpljenjem \u010Dloveka in \u017Eivali ni prakti\u010Dne razlike in da je usmrtitev iz usmiljenja humana.\"]}}},{\"naslov\":\"Dr\u017Eavna platforma za umetno inteligenco: Golobova vlada \u017Eeli v Slovenijo pripeljati\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"Tanja Brki\u0107\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Slovenija pod vodstvom premierja Roberta Goloba je objavila razpis za nacionalno platformo generativne umetne inteligence, ki obljublja brezpla\u010Den, varen in EU-skladen dostop do vodilnih jezikovnih modelov za vse dr\u017Eavljane, podjetja, javni sektor in raziskovalce \u2013 z ambicijo postati prva dr\u017Eava na svetu s tak\u0161no pogodbo in prora\u010Dunom 10\",\"url\":\"https:\/\/nova24tv.si\/drzavna-platforma-za-umetno-inteligenco-golobova-vlada-zeli-v-slovenijo-pripeljati-orwellov-1984\/\",\"id\":\"27.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek kritizira vladni na\u010Drt za vzpostavitev nacionalne platforme generativne umetne inteligence kot drag in ideolo\u0161ko tvegan projekt.\",\"highlights\":[\"Vlada Roberta Goloba na\u010Drtuje 10 milijonov evrov vreden projekt za brezpla\u010Den dostop do jezikovnih modelov UI za vse dr\u017Eavljane.\",\"Kritiki, vklju\u010Dno z \u017Digo Turkom, opozarjajo na nevarnost dr\u017Eavne indoktrinacije in vgrajevanja ideolo\u0161kih pristranskosti v sistem.\",\"Avtorica izpostavlja, da Slovenija ni prva na svetu s tak\u0161no ponudbo in da bi se javni denar lahko porabil za bolj nujne potrebe dr\u017Eavljanov.\"]},\"nasprotniki\":{\"povzetek\":\"\u010Clanek v enem izmed poudarkov omenja nevarnosti zakona o evtanaziji, ki ga ozna\u010Duje za tveganega za vsakega posameznika.\",\"highlights\":[\"\\\"Luknje v zakonu o evtanaziji, v katere lahko pade vsak\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Nekateri zagovorniki usmrtitve bolnikov gredo tako dale\u010D, da \u010Dlove\u0161ko \u017Eivljenje\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"A. H.\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V \u010Dasu pribli\u017Eevanja referenduma o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki bo 23. novembra Letos, je Metka Zevnlk, predsednica Zdru\u017Eenja starih star\u0161ev, opozorila, kako daLe\u010D so sposobni iti nekateri zagovorniki zastrupitve bolnikov- in sicer v vle\u010Denje vzporednice med \u010Dlovekom In psom.\",\"url\":\"https:\/\/nova24tv.si\/nekateri-zagovorniki-usmrtitve-bolnikov-gredo-tako-dalec-da-clovesko-zivljenje-primerjajo-s-pasjim\/\",\"id\":\"28.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek poro\u010Da o ostrih kritikah nasprotnikov Zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki opozarjajo na neprimerne primerjave med ljudmi in \u017Eivalmi ter nevarnosti zlorab.\",\"highlights\":[\"Metka Zevnik in Ale\u0161 Primc sta izpostavila eti\u010Dne pomisleke glede izena\u010Devanja usmrtitve trpe\u010Dih ljudi z uspavanjem hi\u0161nih ljubljen\u010Dkov.\",\"Nasprotniki zakona opozarjajo na zgodovinske vzporednice z nacisti\u010Dnimi programi evtanazije in psiholo\u0161ki pritisk na bolne.\",\"Namesto zakonske ureditve kon\u010Danja \u017Eivljenja kritiki predlagajo izbolj\u0161anje paliativne in dolgotrajne oskrbe v Sloveniji.\"]},\"nasprotniki\":{\"povzetek\":\"Metka Zevnik, Ale\u0161 Primc in Zdru\u017Eenje starih star\u0161ev ostro nasprotujejo zakonu, ki ga ozna\u010Dujejo za 'zastrupitev' in opozarjajo na razvrednotenje \u010Dlove\u0161kega \u017Eivljenja.\",\"highlights\":[\"\\\"Tako dale\u010D smo pri\u0161li, da \u010Dlove\u0161ko \u017Eivljenje primerjamo s pasjim.\\\"\",\"\\\"Veste, kje so bile milostne usmrtitve? 'Gnadentod' 1. decembra 1938 je Adolf Hitler zadol\u017Eil zdravnike...\\\"\",\"\\\"Zavra\u010Dam usmrtitev \u010Dloveka. To ni niti pomo\u010D in niti re\u0161itev. Je priznanje na\u0161ega neuspeha dru\u017Ebe.\\\"\",\"\\\"Uzakonitev medicinske zastrupitve bi imela psiholo\u0161ki pritisk na dolgotrajno bolne, na kroni\u010Dne bolnike in tudi na umirajo\u010De.\\\"\",\"\\\"Kak\u0161no sporo\u010Dilo boste dali otroku, ko boste eno uro nazaj dali ubit va\u0161o staro mamo?\\\"\",\"\\\"\u017Dal pa ne zmore ta vlada urediti niti dolgotrajne oskrbe niti paliativne... in to spravlja danes starej\u0161e in bolj bolne ljudi v obup.\\\"\"]},\"podporniki\":{\"povzetek\":\"V \u010Dlanku je kot zagovornica omenjena Nina Beyokol, ki zagovarja pravico do pomo\u010Di pri kon\u010Danju \u017Eivljenja skozi primerjavo z usmiljenjem do trpe\u010Dih \u017Eivali.\",\"highlights\":[\"\\\"\u010Ce pogledamo psa, ki trpi, ponavadi, \u010De smo dobri lastniki, tega psa damo tudi usmrtiti. Ga damo uspavati, zato ker ga te\u017Eko gledamo, kako trpi. Ne vem, zakaj bi delali neko razliko pri \u010Dloveku.\\\"\",\"\\\"Zakaj pa ho\u010Demo gledati \u010Dloveka, svojega bli\u017Enjega, kako trpi, \u010De tega ne \u017Eeli?\\\"\"]}}},{\"naslov\":\"SDS na seji Odbora za zdravstvo predstavila celovit na\u010Drt za re\u0161itev krize v zdravstvu\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"Tanja Brki\u0107\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Poslanska skupina Slovenske demokratske stranke (SDS) z vodjo Jelko Godec na \u010Delu je danes na nujni seji Odbora za zdravstvo Dr\u017Eavnega zbora predstavila obse\u017Een paket ukrepov pod naslovom \u201CKako naprej v slovenskem javnem zdravstvenem sistemu po koncu Golobove vlade\u201D.\",\"url\":\"https:\/\/nova24tv.si\/sds-na-seji-odbora-za-zdravstvo-predstavila-celovit-nacrt-za-resitev-krize-v-zdravstvu\/\",\"id\":\"32.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Poslanska skupina SDS je na nujni seji Odbora za zdravstvo predstavila obse\u017Een paket \u0161estih klju\u010Dnih ukrepov za re\u0161evanje slovenskega zdravstvenega sistema, ki je po njihovem mnenju pred kolapsom.\",\"highlights\":[\"SDS predlaga vzpostavitev lo\u010Denega pla\u010Dnega stebra za zdravstvo z znatnim povi\u0161anjem pla\u010D za specialiste in medicinske sestre do januarja 2026.\",\"Na\u010Drt vklju\u010Duje podelitev statusa svobodnega zdravnika po avstrijskem vzoru, digitalizacijo \u010Dakalnih vrst v realnem \u010Dasu in administrativno razbremenitev sistema.\",\"Jelka Godec je poudarila, da gre za vpra\u0161anje pre\u017Eivetja sistema in pozvala ministrstvo, naj v 14 dneh pripravi akcijski na\u010Drt za izvedbo teh ukrepov.\"]},\"nasprotniki\":{\"povzetek\":\"\u010Clanek vklju\u010Duje povezavo na sorodno vsebino, ki opozarja na nevarnosti in pomanjkljivosti zakonodaje o evtanaziji.\",\"highlights\":[\"\\\"Luknje v zakonu o evtanaziji, v katere lahko pade vsak\\\"\"]},\"podporniki\":null}},{\"naslov\":\"[Video] Koalicija z volivci naslavlja ljudem pomembne teme\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"ninzoh\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"V okviru turneje \u201CKoalicija z volivci za ustavno ve\u010Dino razuma\u201D se je dolgoletni predsednik stranke SDS Janez Jan\u0161a ustavil v Polhovem Gradcu. Gre za pogovore, s katerimi \u017Eelijo v stranki svoj program pribli\u017Eati tudi tistim volivcem, ki jih do sedaj niso uspeli dose\u010Di. Med drugim tudi na ra\u010Dun pristranskega poro\u010Danja osrednjih medijev.\",\"url\":\"https:\/\/nova24tv.si\/video-koalicija-z-volivci-naslavlja-ljudem-pomembne-teme\/\",\"id\":\"33.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Janez Jan\u0161a je v okviru turneje v Polhovem Gradcu izpostavil klju\u010Dne programske to\u010Dke SDS, vklju\u010Dno s kritikami vladne demografske politike, romske problematike in nasprotovanjem zakonu o evtanaziji.\",\"highlights\":[\"Jan\u0161a opozarja na staranje prebivalstva in kritizira ukinitev Urada za demografijo ter zana\u0161anje na migracije kot re\u0161itev.\",\"Glede romske problematike SDS zagovarja dosledno izvajanje obstoje\u010Dih zakonov in pogojevanje socialne pomo\u010Di z obiskovanjem \u0161ole.\",\"Predsednik SDS poziva volivce, naj na referendumu 23. novembra zavrnejo zakon o evtanaziji, ki mu nasprotuje tudi medicinska stroka.\"]},\"nasprotniki\":{\"povzetek\":\"Janez Jan\u0161a in stranka SDS ostro nasprotujejo zakonu o evtanaziji, pri \u010Demer poudarjajo ustavno nedotakljivost \u017Eivljenja, verska na\u010Dela in eti\u010Dne zadr\u017Eke medicinske stroke.\",\"highlights\":[\"\\\"Bli\u017Ea pa se tudi referendum o evtanaziji, ki ji medicinska stroka nasprotuje.\\\"\",\"\\\"Ne gre le za moralno ali eti\u010Dno vpra\u0161anje, temve\u010D tudi za vpra\u0161anje upo\u0161tevanja slovenske ustave, v kateri je v 17. \u010Dlenu zapisano, da je \u010Dlove\u0161ko \u017Eivljenje nedotakljivo.\\\"\",\"\\\"Jan\u0161a je opomnil, da za kristjane velja tudi peta bo\u017Eja zapoved 'ne ubijaj'.\\\"\",\"\\\"Svoje nestrinjanje z zakonom, ki bi bolniku namesto laj\u0161anja bole\u010Din ponudil zastrupitev in od zdravnikov zahteval, da kr\u0161ijo svojo prisego, bodo volivci lahko pokazali \u017Ee 23. novembra.\\\"\",\"\\\"Je pa zelo zanimivo, da levi\u010Darji v Sloveniji oziroma levica, ki je ta zakon predlagala in sprejela, ob vsaki priliki govori o tem, kako je potrebno spo\u0161tovati institucije... se pa tukaj kr\u0161i vse to na najbolj bazi\u010Dni to\u010Dki.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Nekateri zagovorniki usmrtitve bolnikov gredo tako dale\u010D, da \u010Dlove\u0161ko \u017Eivljenje\",\"medij\":\"nova24tv.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"ninzoh\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V \u010Dasu pribli\u017Eevanja referenduma o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki bo 23. novembra letos, je Metka Zevnik, predsednica Zdru\u017Eenja starih star\u0161ev, opozorila, kako dale\u010D so sposobni iti nekateri zagovorniki zastrupitve bolnikov \u2013 in sicer v vle\u010Denje vzporednice med \u010Dlovekom in psom.\",\"url\":\"https:\/\/nova24tv.si\/nekateri-zagovorniki-usmrtitve-bolnikov-gredo-tako-dalec-da-clovesko-zivljenje-primerjajo-s-pasjim\/\",\"id\":\"34.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek poro\u010Da o ostrih kritikah Metke Zevnik in Ale\u0161a Primca glede Zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki ga ozna\u010Dujeta za nevaren dru\u017Ebeni neuspeh.\",\"highlights\":[\"Metka Zevnik opozarja na neprimerne primerjave med usmrtitvijo trpe\u010Dih \u017Eivali in ljudi, ki so se pojavile v javnih razpravah.\",\"Nasprotniki zakona vle\u010Dejo vzporednice med evtanazijo in nacisti\u010Dnim programom 'Gnadentod' za usmrtitev du\u0161evnih bolnikov.\",\"Ale\u0161 Primc poudarja, da bi uzakonitev pomo\u010Di pri kon\u010Danju \u017Eivljenja poslala napa\u010Dno sporo\u010Dilo mladim glede vrednosti boja za \u017Eivljenje.\"]},\"nasprotniki\":{\"povzetek\":\"Metka Zevnik in Ale\u0161 Primc ostro nasprotujeta zakonu, pri \u010Demer uporabljata zgodovinske primerjave z nacizmom in opozarjata na razvrednotenje \u010Dlove\u0161kega \u017Eivljenja.\",\"highlights\":[\"\\\"Zavra\u010Dam usmrtitev \u010Dloveka. To ni niti pomo\u010D in niti re\u0161itev. Je priznanje na\u0161ega neuspeha dru\u017Ebe.\\\"\",\"\\\"Veste, kje so bile milostne usmrtitve? \u2018Gnadentod\u2019. 1. decembra 1938 je Adolf Hitler zadol\u017Eil zdravnike, dolo\u010Dene po imenu, ki naj izvr\u0161ijo \u2018Gnadentod\u2019 pri du\u0161evnih bolnikih.\\\"\",\"\\\"Moderno je \u010Dloveka zastrupiti, ko ga boli, ko umira, ga malo prisiliti, da bo malo prej. Ker kot smo sli\u0161ali, je ceneje.\\\"\",\"\\\"Uzakonitev medicinske zastrupitve bi imela psiholo\u0161ki pritisk na dolgotrajno bolne, na kroni\u010Dne bolnike in tudi na umirajo\u010De.\\\"\",\"\\\"Kak\u0161no sporo\u010Dilo boste dali otroku, ko boste eno uro nazaj dali ubit va\u0161o staro mamo?\\\"\"]},\"podporniki\":{\"povzetek\":\"V \u010Dlanku je kot zagovornica omenjena Nina Beyokol, ki zagovarja pravico do pomo\u010Di pri kon\u010Danju \u017Eivljenja na podlagi prepre\u010Devanja nepotrebnega trpljenja.\",\"highlights\":[\"\\\"\u010Ce pogledamo psa, ki trpi, ponavadi, \u010De smo dobri lastniki, tega psa damo tudi usmrtiti. Ga damo uspavati, zato ker ga te\u017Eko gledamo, kako trpi. Ne vem, zakaj bi delali neko razliko pri \u010Dloveku.\\\"\",\"\\\"Zakaj pa ho\u010Demo gledati \u010Dloveka, svojega bli\u017Enjega, kako trpi, \u010De tega ne \u017Eeli?\\\"\"]}}},{\"naslov\":\"To so luknje v zakonu o evtanaziji, v katere lahko pade vsak\",\"medij\":\"novice.najdi.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Pi\u0161e: A. H. Predsednica Centra za avtizem in mama otroka z avtizmom Vesna Malen\u0161ek je v svojem zapisu na Facebooku podrobno analizirala Zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja (ZPPK\u017D), ki ga kriti\u010Dno ozna\u010Duje kot zakon, poln lukenj, ki omogo\u010Dajo zlorabe, netransparentnost in tveganja za ranljive posameznike. Opozarja, da\",\"url\":\"https:\/\/novice.najdi.si\/novica\/191cc0b8381e22196729e181ac4f3173\",\"id\":\"36.pdf\",\"contents\":null},{\"naslov\":\"Smrt ni najhuj\u0161e, kar se zgodi \u010Dloveku\",\"medij\":\"novice.najdi.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Ne zmorem napisati znanstvene razprave, s katero bi utemeljevala svojo podporo zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja. Stara sem 90 let in moje ustvarjalne mo\u010Di in energije so v zatonu. Vsekakor pa lahko javno zagotovim, da je med mojimi poslednjimi \u017Eeljami ta, da bi imela mo\u017Enost smrti brez hudega trpljenja in brez izgube\",\"url\":\"https:\/\/novice.najdi.si\/novica\/8c68aa779b823348fe49d89712293570\",\"id\":\"37.pdf\",\"contents\":null},{\"naslov\":\"Nekateri zagovorniki usmrtitve bolnikov gredo tako dale\u010D, da \u010Dlove\u0161ko \u017Eivljenje\",\"medij\":\"novice.najdi.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V \u010Dasu pribli\u017Eevanja referenduma o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki bo 23. novembra letos, je Metka Zevnik, predsednica Zdru\u017Eenja starih star\u0161ev, opozorila, kako dale\u010D so sposobni iti nekateri zagovorniki zastrupitve bolnik...\",\"url\":\"https:\/\/novice.najdi.si\/novica\/ac574b9ae5ea560f448ae9101cd8ffd8\",\"id\":\"38.pdf\",\"contents\":null},{\"naslov\":\"Dr. Ivan \u0160tuhec: Zakaj bi moral kdorkoli sodelovati pri evtanaziji?\",\"medij\":\"novice.najdi.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Referendum Proti zastrupitvi in zlorabam bolnikov se pribli\u017Euje z nezadr\u017Eno hitrostjo. Tega spremlja vrsta eti\u010Dnih dilem, zato smo pred glasovanjem, ki bo potekalo naslednjo nedeljo, spregovorili z moralnim teologom dr. Ivanom \u0160tuhcem. Ta je pre...\",\"url\":\"https:\/\/novice.najdi.si\/novica\/8c8eb0d303409f79c4f02d4b3dca94f2\",\"id\":\"39.pdf\",\"contents\":null},{\"naslov\":\"V novi Demokraciji preberite: Prozorne manipulacije levi\u010Darjev pred referendumom o\",\"medij\":\"novice.najdi.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Pi\u0161e: Ga\u0161per Bla\u017Ei\u010D \u010Ceprav prore\u017Eimske agencije za raziskovanje javnega mnenja pri objavi anket glede referenduma ka\u017Eejo na prepri\u010Dljivo zmago zagovornikov evtanazije, pa dogajanje v politiki ka\u017Ee povsem druga\u010Dno sliko. Povedano druga\u010De: v vrstah zagovornikov zakona, ki legalizira \u00BBsamomor z asistenco\u00AB, dejansko prevladuje veliko nervoze.\",\"url\":\"https:\/\/novice.najdi.si\/novica\/1e1faae0e27ec25658687d608abfc5aa\",\"id\":\"40.pdf\",\"contents\":null},{\"naslov\":\"Sedem verskih skupnosti proti zakonu o prostovoljnem kon\u010Danju \u017Eivljenja\",\"medij\":\"portal24.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"Miha D. Kova\u010D\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V izjavi so navedli, da predlog zakona po njihovem mnenju nasprotuje na\u010Delu nedotakljivosti \u010Dlove\u0161kega \u017Eivljenja. Namesto postopkov, ki vodijo v smrt, se po oceni podpisnikov morajo krepiti paliativna oskrba, pomo\u010D pri laj\u0161anju bole\u010Din in \u010Dlove\u0161ka bli\u017Eina v zadnjem \u017Eivljenjskem obdobju. V Ognji\u0161\u010Du so zapisali, da skupnosti opozarjajo na\",\"url\":\"https:\/\/portal24.si\/sedem-verskih-skupnosti-proti-zakonu-o-prostovoljnem-koncanju-zivljenja\/\",\"id\":\"41.pdf\",\"contents\":null},{\"naslov\":\"Ta strankarska funkcionarka Martinu Golobu svoje povedala kar prek Facebooka\",\"medij\":\"slovenskenovice.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"M. U.\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Priljubljenemu duhovniku je podpredsednica stranke Pirati razlo\u017Eila, da so v Sloveniji po ustavi dr\u017Eava in verske skupnosti lo\u010Dene.\",\"url\":\"https:\/\/www.slovenskenovice.si\/novice\/slovenija\/ta-strankarska-funkcionarka-martinu-golobu-svoje-povedala-kar-prek-facebooka-video\",\"id\":\"43.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek obravnava spor med stranko Pirati in predstavniki Katoli\u0161ke cerkve glede vme\u0161avanja verskih skupnosti v referendumsko kampanjo o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Podpredsednica Piratov Nina Beyokol opozarja na ustavno lo\u010Denost cerkve in dr\u017Eave.\",\"Katoli\u0161ka cerkev zavra\u010Da o\u010Ditke o vme\u0161avanju in trdi, da le izpolnjuje svoje poslanstvo obrambe \u017Eivljenja.\",\"Duhovnik Martin Golob je javno pozval k zavrnitvi zakona o evtanaziji, kar je spro\u017Eilo odziv zagovornikov zakona.\"]},\"nasprotniki\":{\"povzetek\":\"Katoli\u0161ka cerkev in duhovnik Martin Golob nasprotujejo zakonu z utemeljitvijo, da je \u017Eivljenje v domeni Boga in da branijo temeljne moralne vrednote.\",\"highlights\":[\"\\\"Kristjani verjamemo: edini, ki ima pravico nad \u017Eivljenjem in smrtjo, je edinole Bog.\\\"\",\"\\\"Podprimo referendum in dajmo stran ta zakon o evtanaziji.\\\"\",\"Cerkev trdi, da ne vodi politi\u010Dne kampanje, temve\u010D brani \\\"spo\u0161tovanje do \u017Eivljenja in dostojanstva vsakega \u010Dloveka od spo\u010Detja do naravne smrti.\\\"\"]},\"podporniki\":{\"povzetek\":\"Stranka Pirati, koalicijske stranke in dru\u0161tvo Srebrna nit v okviru zavezni\u0161tva Moje \u017Eivljenje, moja pravica podpirajo zakon in opozarjajo na neprimerno vme\u0161avanje cerkve.\",\"highlights\":[\"\\\"Po slovenski ustavi sta cerkev in dr\u017Eava lo\u010Deni.\\\"\",\"\\\"Predstavniki verskih skupnosti imajo vso pravico, da \u017Eivijo, kot \u017Eelijo. Nimajo pa pravice svoje volje vsiljevati vsem ostalim.\\\"\",\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica opozarja, da je Cerkev s svojimi aktivnostmi prestopila zakonske in ustavne okvirje dovoljenega politi\u010Dnega delovanja.\"]}}},{\"naslov\":\"Ta strankarska funkcionarka Martinu Golobu svoje povedala kar prek Facebooka\",\"medij\":\"slovenskenovice.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"M. U.\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Priljubljenemu duhovniku je podpredsednica stranke Pirati razlo\u017Eila, da so v Sloveniji po ustavi dr\u017Eava in verske skupnosti lo\u010Dene.\",\"url\":\"https:\/\/slovenskenovice.delo.si\/novice\/slovenija\/ta-strankarska-funkcionarka-martinu-golobu-svoje-povedala-kar-prek-facebooka-video\",\"id\":\"44.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek obravnava spor med stranko Pirati in Katoli\u0161ko cerkvijo glede vme\u0161avanja verskih skupnosti v referendumsko kampanjo o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Podpredsednica Piratov Nina Beyokol opozarja na ustavno lo\u010Denost cerkve in dr\u017Eave ter poziva verske skupnosti, naj ne vsiljujejo svoje volje drugim.\",\"Katoli\u0161ka cerkev zavra\u010Da o\u010Ditke o vme\u0161avanju in trdi, da le izpolnjuje svoje poslanstvo obrambe \u017Eivljenja od spo\u010Detja do naravne smrti.\",\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica meni, da je Cerkev s svojimi aktivnostmi prestopila zakonske in ustavne okvirje politi\u010Dnega delovanja.\"]},\"nasprotniki\":{\"povzetek\":\"Predstavniki Katoli\u0161ke cerkve in duhovnik Martin Golob nasprotujejo zakonu z moralnimi in verskimi argumenti o svetosti \u017Eivljenja.\",\"highlights\":[\"\\\"Kristjani verjamemo: edini, ki ima pravico nad \u017Eivljenjem in smrtjo, je edinole Bog.\\\"\",\"\\\"Podprimo referendum in dajmo stran ta zakon o evtanaziji.\\\"\",\"Cerkev trdi, da brani \\\"temeljne moralne vrednote, zlasti spo\u0161tovanje do \u017Eivljenja in dostojanstva vsakega \u010Dloveka od spo\u010Detja do naravne smrti.\\\"\"]},\"podporniki\":{\"povzetek\":\"Stranka Pirati, koalicijske stranke in dru\u0161tvo Srebrna nit zagovarjajo zakon ter opozarjajo na neprimerno vme\u0161avanje cerkve v politiko.\",\"highlights\":[\"\\\"Po slovenski ustavi sta cerkev in dr\u017Eava lo\u010Deni.\\\"\",\"\\\"Predstavniki verskih skupnosti imajo vso pravico, da \u017Eivijo, kot \u017Eelijo. Nimajo pa pravice svoje volje vsiljevati vsem ostalim.\\\"\",\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica opozarja, da se predstavniki Cerkve aktivno vklju\u010Dujejo v kampanjo, \u010Deprav niso uradni organizatorji.\"]}}},{\"naslov\":\"Saj se \u0161alijo! Za Pre\u0161ernov rojstni dan ministrstvo za kulturo vabi na kulturno\",\"medij\":\"demokracija.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"C. R.\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Vsak dan znova nas Golobova vlada s \u010Dim preseneti. Tokrat tudi s povabilom, naj \u201Cta veseli dan kulture\u201D ob Pre\u0161ernovem rojstnem dnevu (3. decembra) pre\u017Eivimo v \u2013 Islamskem kulturnem centr...\",\"url\":\"https:\/\/demokracija.si\/fokus\/saj-se-salijo-za-presernov-rojstni-dan-ministrstvo-za-kulturo-vabi-na-kulturno-praznovanje-v-islamski-kulturni-center\/\",\"id\":\"45.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek kritizira odlo\u010Ditev Ministrstva za kulturo, da obele\u017Eitev Pre\u0161ernovega rojstnega dne organizira v Islamskem kulturnem centru, hkrati pa v stranskih rubrikah opozarja na domnevne nevarnosti zakona o evtanaziji.\",\"highlights\":[\"Ministrstvo za kulturo pod vodstvom Aste Vre\u010Dko vabi na brezpla\u010Den ogled Islamskega kulturnega centra in otro\u0161ke delavnice ob obletnici rojstva Franceta Pre\u0161erna.\",\"Avtor \u010Dlanka namiguje na povezavo med vabilom ministrstva, obiskom predsednice dr\u017Eave v Katarju in skupnim pozivom verskih skupnosti proti evtanaziji.\",\"Vsebina izpostavlja vpra\u0161anje primernosti lokacije glede na Pre\u0161ernovo zgodovinsko opisovanje 'mohamedancev' in vlogo ljubljanskega \u017Eupana Zorana Jankovi\u0107a.\"]},\"nasprotniki\":{\"povzetek\":\"Medij Demokracija in verske skupnosti izra\u017Eajo mo\u010Dno nasprotovanje zakonu o evtanaziji, ki ga ozna\u010Dujejo za 'levi\u010Darsko kulturo smrti' in opozarjajo na nevarne zakonske luknje.\",\"highlights\":[\"\\\"To so luknje v zakonu o evtanaziji, v katere lahko pade vsak\\\"\",\"\\\"Prozorne manipulacije levi\u010Darjev pred referendumom o \u017Eivljenju in smrti\\\"\",\"\\\"Za kulturo \u017Eivljenja, proti levi\u010Darski kulturi smrti\\\"\",\"Skupni poziv verskih skupnosti, vklju\u010Dno z Islamsko skupnostjo v Sloveniji, naj se dr\u017Eavljani na referendumu opredelijo PROTI.\"]},\"podporniki\":null}},{\"naslov\":\"Za\u010Dasno prilagojeno poslovanje Upravne enote Ljubljana\",\"medij\":\"gov.si\",\"datum\":\"13. 11. 2025\",\"avtor\":null,\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"13. 11. 2025 Upravna enota Ljubljana Cenjene stranke obve\u0161\u010Damo, da bo v \u010Dasu od torka 18. novembra do \u010Detrtka 20. novembra 2025 v prostorih Upravne enote Ljubljana na lokaciji Linhartova cesta 13 in Toba\u010Dna ulica 5, potekalo pred\u010Dasno glasovanje za izvedbo zakonodajnega referenduma o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja\",\"url\":\"https:\/\/www.gov.si\/novice\/2025-11-13-zacasno-prilagojeno-poslovanje-upravne-enote-ljubljana\/\",\"id\":\"47.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Upravna enota Ljubljana obve\u0161\u010Da o za\u010Dasno prilagojenem poslovanju zaradi izvedbe pred\u010Dasnega glasovanja na referendumu o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Pred\u010Dasno glasovanje bo potekalo od torka, 18. novembra, do \u010Detrtka, 20. novembra 2025.\",\"Glasovanje se bo izvajalo na lokacijah Linhartova cesta 13 in Toba\u010Dna ulica 5 v Ljubljani.\",\"Zaradi izvedbe referendumskih aktivnosti bo delovanje okenc Upravne enote Ljubljana za\u010Dasno prilagojeno.\"]},\"nasprotniki\":null,\"podporniki\":{\"povzetek\":\"Upravna enota Ljubljana kot uradni organ podaja nevtralne, informativne podatke o izvedbi glasovanja za Zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"\\\"v prostorih Upravne enote Ljubljana na lokaciji Linhartova cesta 13 in Toba\u010Dna ulica 5, potekalo pred\u010Dasno glasovanje za izvedbo zakonodajnega referenduma o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja (ZPPK\u017D)\\\"\"]}}},{\"naslov\":\"Razkrito: ve\u010D oskrbovancev \u017Ertev iz\u017Eivljanja negovalke\",\"medij\":\"megasvet.si\",\"datum\":\"13. 11. 2025\",\"avtor\":null,\"oznaka\":[\"SREBRNA NIT\"],\"intro\":\"\u0160e vedno odzvanja grozljiv posnetek iz doma starej\u0161ih v Celju, kjer je negovalka nedostojno ravnala z nepokretno \u017Eensko. A temu je zdaj sledil \u0161e en \u2013 posnetek iz\u017Eivljanja nad vidno oslabljenim mo\u0161kim, v katerem je ista negovalka ponovno\",\"url\":\"https:\/\/www.megasvet.si\/vsebina\/38120\/Razkrito-vec-oskrbovancev-zrtev-izzivljanja-negovalke?from=cat3\",\"id\":\"48.pdf\",\"contents\":null},{\"naslov\":\"Razkrito: ve\u010D oskrbovancev \u017Ertev iz\u017Eivljanja negovalke\",\"medij\":\"megasvet.si\",\"datum\":\"13. 11. 2025\",\"avtor\":null,\"oznaka\":[\"SREBRNA NIT\"],\"intro\":\"\u0160e vedno odzvanja grozljiv posnetek iz doma starej\u0161ih v Celju, kjer je negovalka nedostojno ravnala z nepokretno \u017Eensko. A temu je zdaj sledil \u0161e en \u2013 posnetek iz\u017Eivljanja nad vidno oslabljenim mo\u0161kim, v katerem je ista negovalka ponovno\",\"url\":\"https:\/\/www.megasvet.si\/vsebina\/38120\/Razkrito-vec-oskrbovancev-zrtev-izzivljanja-negovalke?from=cat2\",\"id\":\"51.pdf\",\"contents\":null},{\"naslov\":\"Martin Golob Iskreno o babici: \u00BBNi bila ve\u010D za nobeno rabo \u2026\u00AB (VIDEO)\",\"medij\":\"nadlani.si\",\"datum\":\"13. 11. 2025\",\"avtor\":null,\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"V novi epizodi podcasta Kdo kakor On je Martin Golob razgalil del svoje mladosti, ki ga nosi globoko v srcu. Njegova izpoved o babici je ganila gledalce \u2013 ne\u017Ena, bole\u010Da in presenetljivo univerzalna. Zgodba, ki se dotakne vsakogar Tokrat je Golob ...\",\"url\":\"https:\/\/www.nadlani.si\/show\/martin-golob-iskreno-o-babici-ni-bila-vec-za-nobeno-rabo-video\/\",\"id\":\"53.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek povzema \u010Dustveno izpoved duhovnika Martina Goloba o njegovi babici in razmi\u0161ljanje o dostojanstvu staranja ter minljivosti v okviru podcasta s sestro Emanuelo \u017Derdin.\",\"highlights\":[\"Duhovnik Martin Golob je v podcastu gostil redovnico Emanuelo \u017Derdin, s katero sta razpravljala o staranju, trpljenju in evtanaziji.\",\"Golob je delil ganljivo zgodbo o svoji babici, ki se je po\u010Dutila nekoristno, in o\u010Detovem odgovoru, da je njena vrednost v samem obstoju in ljubezni.\",\"Pogovor poudarja, da vrednost \u010Dloveka ni v njegovi uporabnosti, temve\u010D v tem, da je ljubljen in da preprosto obstaja.\"]},\"nasprotniki\":{\"povzetek\":\"\u010Clanek skozi osebno zgodbo in kr\u0161\u010Dansko perspektivo posredno zavra\u010Da idejo evtanazije s poudarjanjem neodtujljive vrednosti \u017Eivljenja ne glede na njegovo 'uporabnost'.\",\"highlights\":[\"\\\"Vrednost \u010Dloveka ni v uporabnosti, temve\u010D v tem, da je. Da obstaja. Da ljubi in je ljubljen.\\\"\",\"\\\"\u010Clovek ni 'koristen' ali 'nekoristen'. \u010Clovek je. In to je dovolj.\\\"\",\"\\\"Ja mama, saj niste zato, ker bi vas nekaj rabili\u2026 Saj je tako lepo, ker ste.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Zgodbe o nevarnostih, ki jih uvedba evtanazije lahko prinese: kak\u0161ne so izku\u0161nje\",\"medij\":\"notranjska.si\",\"datum\":\"13. 11. 2025\",\"avtor\":null,\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Uvedba evtanazije v slovenski dru\u017Ebi buri duhove; zdravniki vztrajajo, da zaradi Hipokratove prisege niso zavezani smrti, toda \u017Eivljenju. Opozicija izpostavlja nujnost ureditve dostojne in profesionalne paliativne oskrbe ter vztraja pri svetosti \u017Eivljenja, medtem ko koalicija vztraja pri svojem: prostovoljno kon\u010Danje \u017Eivljenja naj postane legalna mo\u017Enost\",\"url\":\"https:\/\/notranjska.si\/zgodbe-o-nevarnostih-ki-jih-uvedba-evtanazije-lahko-prinese-kaksne-so-izkusnje-drzav\/\",\"id\":\"56.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek pred prihajajo\u010Dim referendumom izpostavlja nevarnosti in eti\u010Dne dileme uvedbe evtanazije, pri \u010Demer se opira na negativne izku\u0161nje iz tujine in mnenja slovenskih nasprotnikov.\",\"highlights\":[\"Avtor opozarja na primere iz Belgije in Kanade, kjer so evtanazijo odobrili zaradi du\u0161evnih stisk, rev\u0161\u010Dine ali neprimernih bivalnih pogojev.\",\"Slovenski zdravniki in opozicija poudarjajo svetost \u017Eivljenja ter nujnost ureditve kakovostne paliativne oskrbe namesto uvajanja pomo\u010Di pri samomoru.\",\"Izpostavljena je bojazen, da bi legalizacija evtanazije vodila v 'drsenje po spolzki poti', kjer bi \u017Eivljenje starej\u0161ih in bolnih postalo manj vredno.\"]},\"nasprotniki\":{\"povzetek\":\"Nasprotniki, vklju\u010Dno z zdravniki, opozicijo (SDS) in strokovnjaki, svarijo pred 'kulturo smrti' in zlorabami sistema, ki bi lahko vodile v evtanazijo ranljivih skupin.\",\"highlights\":[\"\\\"Ko dru\u017Eba za\u010Dne sprejemati zakone, ki dovoljujejo pomo\u010D pri samomoru, se to lahko hitro spremeni v drsenje po spolzki poti.\\\"\",\"\\\"Najprej iz usmiljenja, nato iz ob\u010Dutka bremena \u2026 in nenadoma \u017Eivljenje starej\u0161ih ali bolnih postane manj vredno.\\\"\",\"\\\"Namesto da ponujamo samomor kot re\u0161itev, moramo razvijati paliativno in socialno oskrbo \u2013 graditi dru\u017Ebo so\u010Dutja in pomo\u010Di.\\\"\",\"\\\"V Kanadi pa so na primer dokumentirani primeri ljudi, ki so prosili za evtanazijo zaradi rev\u0161\u010Dine, dolgih \u010Dakalnih dob, nezmo\u017Enosti financiranja svojih otrok.\\\"\",\"\\\"Zdravniki vztrajajo, da zaradi Hipokratove prisege niso zavezani smrti, toda \u017Eivljenju.\\\"\",\"\\\"Opozicija izpostavlja nujnost ureditve dostojne in profesionalne paliativne oskrbe ter vztraja pri svetosti \u017Eivljenja.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki evtanazije so v \u010Dlanku omenjeni le be\u017Eno kot koalicija, ki si prizadeva za legalizacijo prostovoljnega kon\u010Danja \u017Eivljenja.\",\"highlights\":[\"\\\"Koalicija vztraja pri svojem: prostovoljno kon\u010Danje \u017Eivljenja naj postane legalna mo\u017Enost tudi v Sloveniji.\\\"\"]}}},{\"naslov\":\"\u0160okantno vedenje negovalke v Celju: Pristojni ukrepali prepozno?\",\"medij\":\"telegraf.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"Uredni\u0161tvo\",\"oznaka\":[\"SREBRNA NIT\"],\"intro\":\"V domu starej\u0161ih v Celju je pri\u0161lo do pretresljivega incidenta, kjer je negovalka neprimerno ravnala z ve\u010D oskrbovanci. Posnetki, ki so se pojavili na dru\u017Ebenih omre\u017Ejih, razkrivajo nedostojno vedenje negovalke do nepokretne \u017Eenske in oslabljenega mo\u0161kega. Kljub temu, da je bil posnetek star dve leti, je \u0161ele zdaj pri\u0161el v javnost. Je sistem odzivanja na\",\"url\":\"https:\/\/telegraf.si\/sokantno-vedenje-negovalke-v-celju-pristojni-ukrepali-prepozno\/\",\"id\":\"59.pdf\",\"contents\":null},{\"naslov\":\"Je v Ljubljani z no\u017Eem mesaril migrant?\",\"medij\":\"telex.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Na Bavarskem dvoru v Ljubljani je neznani osumljenec po do zdaj znanih podatkih z ostrim predmetom huje po\u0161kodoval voznika avtobusa in po dogodku pobegnil. Po podatkih iz socialnih omre\u017Eij naj bi bil storilec migrant. V popoldanskih urah se je na avtobusu Ljubljanskega potni\u0161kega prometa dogajala prava drama. Pri\u010De so za STA povedale, da sta se\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5863456\",\"id\":\"61.pdf\",\"contents\":null},{\"naslov\":\"Nekateri zagovorniki usmrtitve bolnikov gredo tako dale\u010D, da \u010Dlove\u0161ko \u017Eivljenje pri.\",\"medij\":\"telex.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V \u010Dasu pribli\u017Eevanja referenduma o Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, ki bo 23. novembra letos, je Metka Zevnik, predsednica Zdru\u017Eenja starih star\u0161ev, opozorila, kako dale\u010D so sposobni iti nekateri zagovorniki zastrupitve bolnikov \u2013 in sicer v vle\u010Denje vzporednice med \u010Dlovekom in psom. \\\"\u010Ce pogledamo psa, ki trpi, ponavadi, \u010De\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5862837\",\"id\":\"62.pdf\",\"contents\":null},{\"naslov\":\"SDS na seji Odbora za zdravstvo predstavila celovit na\u010Drt za re\u0161itev krize v z...\",\"medij\":\"telex.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Poslanska skupina Slovenske demokratske stranke (SDS) z vodjo Jelko Godec na \u010Delu je danes na nujni seji Odbora za zdravstvo Dr\u017Eavnega zbora predstavila obse\u017Een paket ukrepov pod naslovom \\\"Kako naprej v slovenskem javnem zdravstvenem sistemu po koncu Golobove vlade\\\". Zahteva za sklic seje, ki jo je 30. oktobra 2025 vlo\u017Eila koalicija, je\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5862981\",\"id\":\"63.pdf\",\"contents\":null},{\"naslov\":\"Zdravje - Nasprotovanje Zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja\",\"medij\":\"telex.si\",\"datum\":\"13. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Slovenske zdravni\u0161ke organizacije: \u010Ce \u017Eelimo pomagati, potrebujemo Zakon o paliativni oskrbi in ne o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5862599\",\"id\":\"64.pdf\",\"contents\":null},{\"naslov\":\"Je Cerkev prestopila meje ustavnega?\",\"medij\":\"Delo\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Uro\u0161 Esih, Barbara Er\u017Een\",\"oznaka\":[\"SREBRNA NIT\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\",\"EVTANAZIJA\"],\"intro\":\"Referendum V kampanjo je vklju\u010Denih 33 organizatorjev, med njimi uradno ni Katoli\u0161ke cerkve\",\"url\":null,\"id\":\"65.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek obravnava polemike glede vklju\u010Ditve Katoli\u0161ke cerkve v referendumsko kampanjo o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"V kampanjo za referendum je vklju\u010Denih 33 organizatorjev, med katerimi uradno ni Katoli\u0161ke cerkve.\",\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica je Nad\u0161kofijo Ljubljana prijavilo in\u0161pektoratu zaradi domnevnih kr\u0161itev zakona o volilni in referendumski kampanji.\",\"Sociolog religije dr. Marjan Smrke ocenjuje na\u010Din mobilizacije in argumentacije vrha slovenske RKC kot problemati\u010Den in v delih zavr\u017Een.\"]},\"nasprotniki\":{\"povzetek\":\"Katoli\u0161ka cerkev ter zdravni\u0161ke in verske organizacije nasprotujejo zakonu z izpostavljanjem svetosti \u017Eivljenja in izra\u017Eanjem vsebinskih pomislekov.\",\"highlights\":[\"Zdravni\u0161ke in verske organizacije \\\"opozarjajo na nekatere pomisleke in izpostavljajo svetost \u017Eivljenja\\\".\",\"Katoli\u0161ka cerkev se je \\\"na strani proti mo\u010Dno anga\u017Eirala\\\" kljub temu, da ni uradna organizatorka kampanje.\",\"Vrh slovenske RKC uporablja na\u010Din mobilizacije in argumentacije, ki je po mnenju kritikov v nekaterih delih celo \\\"zavr\u017Een\\\".\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona, zbrani okoli dru\u0161tva Srebrna nit in zavezni\u0161tva Moje \u017Eivljenje, moja pravica, zagovarjajo pravico do dostojanstvenega konca in opozarjajo na nepravilnosti nasprotnikov.\",\"highlights\":[\"Podporniki poudarjajo, da bi \\\"vsakdo moral imeti pravico do odlo\u010Danja o svojem \u017Eivljenju\\\".\",\"Zagovorniki izpostavljajo \\\"pravico do mirnega, nadzorovanega in dostojanstvenega konca\\\".\",\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica trdi, da je Cerkev v kampanji \\\"prestopila predvidene zakonske in ustavne okvire dovoljenega\\\".\"]}}},{\"naslov\":\"Pomo\u010D pri prostovoljnem kon\u010Danju \u017Eivljenja: kaj je res in kaj ni\",\"medij\":\"Delo\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Barbara Er\u017Een\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Kaj morate vedeti Izpostavljamo klju\u010Dne poudarke, ki jih je dobro poznati pred odlo\u010Danjem na referendumu\",\"url\":null,\"id\":\"67.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek podrobno predstavlja klju\u010Dne poudarke in postopkovne varovalke predloga zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja pred prihajajo\u010Dim referendumom.\",\"highlights\":[\"Pravico bi imeli polnoletni pacienti z neozdravljivo boleznijo in neznosnim trpljenjem, ki ni posledica du\u0161evne bolezni.\",\"Postopek vklju\u010Duje ve\u010Dkratne pogovore z le\u010De\u010Dim zdravnikom, mnenja neodvisnih strokovnjakov in kon\u010Dno odlo\u010Ditev pet\u010Dlanske komisije.\",\"Zakon ne predvideva evtanazije, temve\u010D pomo\u010D pri kon\u010Danju \u017Eivljenja, kjer mora pacient v postopku aktivno sodelovati.\"]},\"nasprotniki\":{\"povzetek\":\"Zdravni\u0161ke in verske organizacije izra\u017Eajo eti\u010Dne pomisleke glede svetosti \u017Eivljenja in opozarjajo na morebitne dru\u017Ebene pritiske na ranljive skupine.\",\"highlights\":[\"Zdravni\u0161ke in verske organizacije 'opozarjajo na nekatere pomisleke in izpostavljajo svetost \u017Eivljenja'.\",\"Zdravniki ocenjujejo, 'da je neznosno trpljenje te\u017Eko opredeliti'.\",\"Obstaja skrb, 'da bi spremembe lahko prinesle novo dojemanje dostojanstva \u017Eivljenja ter dojemanje te pravice kot nujne'.\",\"Starej\u0161i in hudo bolni bi se lahko 'po\u010Dutili kot breme svojcem'.\"]},\"podporniki\":{\"povzetek\":\"Dru\u0161tvo Srebrna nit in koalicija zagovarjata pravico posameznika do dostojanstvenega konca \u017Eivljenja ob strogih zakonskih varovalkah.\",\"highlights\":[\"Podporniki in pobudniki iz dru\u0161tva Srebrna nit poudarjajo 'pravico do mirnega, nadzorovanega in dostojanstvenega konca'.\",\"Zakon vklju\u010Duje \u0161tevilne varovalke, kot je mo\u017Enost ugovora vesti za zdravstvene delavce.\",\"Predlog zakona temelji na volji 54,89 odstotka volivcev, ki so se o tem podro\u010Dju opredelili na posvetovalnem referendumu.\"]}}},{\"naslov\":\"Problemati\u010Dna referendumska agitacija vrha RKC\",\"medij\":\"Delo\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Uro\u0161 Esih\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Kampanja Za zakonodajni referendum o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja seje na strani proti mo\u010Dno anga\u017Eirala tudi Cerkev\",\"url\":null,\"id\":\"68.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek obravnava prijavo Nad\u0161kofije Ljubljana na in\u0161pektorat zaradi domnevno nezakonitega in organiziranega vme\u0161avanja Rimskokatoli\u0161ke cerkve v referendumsko kampanjo o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica je RKC prijavilo in\u0161pektoratu za notranje zadeve zaradi kr\u0161itve zakona o volilni in referendumski kampanji.\",\"Sociolog Marjan Smrke opozarja, da Cerkev z uporabo verskih simbolov in stra\u0161enjem vernikov izvaja nepo\u0161teno mobilizacijo proti zakonu.\",\"RKC o\u010Ditke o vme\u0161avanju zavra\u010Da s trditvijo, da ne vodijo politi\u010Dne kampanje, temve\u010D le izpolnjujejo svoje versko poslanstvo.\"]},\"nasprotniki\":{\"povzetek\":\"Rimskokatoli\u0161ka cerkev (RKC) pod vodstvom nad\u0161kofov Zoreta in Sajeta aktivno nasprotuje zakonu z moralno obsodbo in primerjavami z zgodovinskimi grozotami.\",\"highlights\":[\"\u0160kof Andrej Saje in nad\u0161kof Stanislav Zore zakon razumeta kot \\\"legalizacijo ubijanja\\\".\",\"Nad\u0161kof Zore je v pastirskem pismu mo\u017Enost, ki jo odpira zakon, primerjal z \\\"nacisti\u010Dno evtanazijo\\\".\",\"Cerkev se pri nasprotovanju sklicuje na Mojzesovo zapoved \\\"Ne ubijaj!\\\".\"]},\"podporniki\":{\"povzetek\":\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica, ki vklju\u010Duje koalicijske stranke in Srebrno nit, zagovarja spo\u0161tovanje zakonodaje o kampanji in ustavno lo\u010Denost dr\u017Eave od verskih skupnosti.\",\"highlights\":[\"Zavezni\u0161tvo trdi, da je RKC v kampanji \\\"prestopila predvidene zakonske in ustavne okvire dovoljenega\\\".\",\"Lenart \u017Davbi (Gibanje Svoboda) ocenjuje, da Cerkev v kampanji zlorablja politi\u010Dne stranke, kot je NSi, za prikrito delovanje.\",\"Sociolog Marjan Smrke izpostavlja, da bo zaradi staranja prebivalstva in sekularizacije \\\"podalj\u0161evanje nepotrebnega trpljenja vse te\u017Eje prepri\u010Dljivo osmi\u0161ljati\\\".\"]}}},{\"naslov\":\"Ljudje volijo zase, ne glede na to, kaj s tem izvolijo za medicino\",\"medij\":\"Delo\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Alojz Ihan\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"To je nevarna igra, saj je spo\u0161tovanje strokovne avtonomije vsake poklicne skupine osnovni pogoj za zahtevo po odgovornosti, v medicini predvsem odgovornosti do bolnika.\",\"url\":null,\"id\":\"70.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Avtor Alojz Ihan v svojem komentarju opozarja na globok doktrinarni prelom in nasilje nad medicinsko stroko, ki ga prina\u0161a predlagani zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Zakonodajalec je mimo privolitve stroke zdravnike in zdravstvene delavce potisnil v vlogo izvr\u0161evalcev asistence pri samomoru.\",\"Avtor predlaga, da bi namesto \u0161iroke mre\u017Ee zdravstvenih domov storitev izvajali specializirani centri zunaj rednega zdravstva.\",\"Spo\u0161tovanje strokovne avtonomije je osnovni pogoj za odgovornost v medicini, ki se z novim zakonom nevarno spodkopava.\"]},\"nasprotniki\":{\"povzetek\":\"Alojz Ihan kot predstavnik medicinske stroke kritizira zakonodajalca zaradi vsiljevanja asistence pri samomoru kot obvezne zdravstvene storitve brez soglasja stroke.\",\"highlights\":[\"\\\"Pisci zakona so mimo privolitve stroke in v namen izvr\u0161ljivosti \u017Eelje volivca, potisnili zdravnike in zdravstvene delavce v enega najve\u010Djih doktrinarnih prelomov v medicinski zgodovini.\\\"\",\"\\\"Zakonodajalec se nima pravice izgovarjati, \u010De\u0161 da je vse v zakonu volja volivca in v demokraciji je to svetinja.\\\"\",\"\\\"Zakon nedvoumno uvaja zakonsko dol\u017Enost zdravnikov, medicinskih sester in drugih zdravstvenih delavcev, da sodelujejo v postopkih pomo\u010Di pri kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"To je nevarna igra, saj je spo\u0161tovanje strokovne avtonomije vsake poklicne skupine osnovni pogoj za zahtevo po odgovornosti.\\\"\",\"\\\"Brez tega smo vsi le \u0161e izvr\u0161evalci birokratskih pravil in zakonov, strokovne razprave pa se preselijo v odvetni\u0161ke pisarne in na sodi\u0161\u010Da.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona so v \u010Dlanku opisani kot volivci in njihovi politi\u010Dni predstavniki, ki si \u017Eelijo pravico do izbire pri kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"\\\"Slovenski volivec \u017Eeli imeti v rokah pravico do izbire, ki jo opisuje zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Slovenski volivec si, torej, v dolo\u010Denih okoli\u0161\u010Dinah, \u017Eeli imeti pravico do asistirane samousmrtitve!\\\"\",\"\\\"Volivec je v resnici ob odlo\u010Danju sledil le osnovnemu namenu zakona, to je misli na novo pravico, ki bi jo v stiski lahko uporabil.\\\"\"]}}},{\"naslov\":\"Nepresli\u0161ano\",\"medij\":\"Dnevnik\",\"datum\":\"14. 11. 2025\",\"avtor\":null,\"oznaka\":[\"ANDREJ PLETERSKI\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Andrej Pleterski znanstveni svetnik, soavtor ZPPK\u017D\",\"url\":null,\"id\":\"72.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Andrej Pleterski v svojem zapisu kritizira Katoli\u0161ko cerkev zaradi neposrednega in intenzivnega klerikalnega poseganja v referendumsko kampanjo o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Avtor izpostavlja, da je cerkev glasovanje za zakon razglasila za te\u017Eak greh in vernike usmerjala proti zakonu, kar ozna\u010Duje za klerikalni prestop meje.\",\"Cerkev je s pozivi \u0161kofov pri nedeljskih ma\u0161ah klju\u010Dno prispevala k zbiranju zadostnega \u0161tevila podpisov za razpis zakonodajnega referenduma.\",\"Kampanja cerkve je vklju\u010Devala misti\u010Dne elemente, kot so namenske ma\u0161e, molitvene verige in post, ter neposredna navodila nad\u0161kofa Zoreta za glasovanje proti.\"]},\"nasprotniki\":{\"povzetek\":\"Katoli\u0161ka cerkev s podporo strank SDS, NSi in SLS uporablja versko avtoriteto, moralno ustrahovanje in organizacijsko mre\u017Eo za prepre\u010Ditev sprejetja zakona.\",\"highlights\":[\"Glasovanje za uzakonitev pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja so razglasili za te\u017Eak greh.\",\"Vernikom so nakazali, da \\\"tovrstnim gre\u0161nikom ni mesta pri cerkvenem bogoslu\u017Eju\\\".\",\"Zagovarjajo stali\u0161\u010De, da mora vsakdo do\u017Eiveti \\\"o\u010Di\u0161\u010Denje skozi trpljenje\\\", da se dose\u017Ee vrhunec osebnostne rasti.\",\"Trdijo, da ima konec \u017Eivljenja \\\"nedoumljivo vlogo dokon\u010Dne osmislitve \u017Eivljenja\\\".\",\"Nad\u0161kof Stanislav Zore je objavil podobo glasovnice z obkro\u017Eenim \\\"PROTI\\\" in pozval k tak\u0161nemu glasovanju.\"]},\"podporniki\":{\"povzetek\":\"Andrej Pleterski kot soavtor zakona zagovarja avtonomijo dr\u017Eave pri sprejemanju zakonodaje in kritizira vsiljevanje verskih vrednot celotni dru\u017Ebi.\",\"highlights\":[\"Avtor opozarja, da je usmerjanje volilnih glasov s strani cerkve poseg v postopek, ki je \\\"v domeni dr\u017Eave\\\".\",\"Izpostavlja, da \\\"du\u0161ebri\u017Eni\u0161ki pristop ne razume, da ga drugi ne marajo, ker ne delijo vrednot du\u0161ebri\u017Enikov\\\".\",\"Zapis zagovarja pravico do prostovoljnega kon\u010Danja \u017Eivljenja brez klerikalnega vme\u0161avanja v osebne odlo\u010Ditve posameznikov.\"]}}},{\"naslov\":\"Pustite nas pri miru\",\"medij\":\"Mladina\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Gorazd Cuznar\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Mladina, \u0161t. 45\",\"url\":null,\"id\":\"73.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Avtor Gorazd Cuznar v pismu bralcev ostro kritizira nad\u0161kofa Stanislava Zoreta zaradi njegove primerjave zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja s Hitlerjevimi ukazi.\",\"highlights\":[\"Nad\u0161kof Stanislav Zore je zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja primerjal s Hitlerjevim ukazom o pobijanju ranjencev med drugo svetovno vojno.\",\"Avtor pisma tak\u0161no primerjavo ozna\u010Duje za sprevr\u017Eeno, hipokriti\u010Dno in \u017Ealjivo do predlagateljev zakona ter dr\u017Eavljanov, ki so ga podprli na referendumu.\",\"V besedilu je izpostavljen zgodovinski kontrast med kolaboracijo ljubljanske \u0161kofije z okupatorjem in pokon\u010Dno dr\u017Eo mariborskega \u0161kofa Ivana Jo\u017Eefa Toma\u017Ei\u010Da.\"]},\"nasprotniki\":{\"povzetek\":\"Ljubljanski nad\u0161kof Stanislav Zore in slovenska Rimskokatoli\u0161ka cerkev nasprotujeta zakonu z uporabo ekstremnih zgodovinskih primerjav.\",\"highlights\":[\"Nad\u0161kof Stanislav Zore je v svoji pridigi zakon \\\"primerjal s Hitlerjevim ukazom o pobijanju ranjencev med drugo svetovno vojno\\\".\",\"Avtor izpostavlja hipokrizijo RKC, ki \u0161e do danes ni v celoti priznala izdajstva in zlo\u010Dinov med vojno, a hkrati kritizira sodobno zakonodajo.\",\"Nasprotniki s tak\u0161nimi izjavami po mnenju avtorja \u017Ealijo parlament in dr\u017Eavljane, ki so vsebino zakona podprli na posvetovalnem referendumu.\"]},\"podporniki\":{\"povzetek\":\"Avtor pisma Gorazd Cuznar in dr\u017Eavljani, ki so glasovali na referendumu, podpirajo zakon kot legitimno voljo ljudstva in zavra\u010Dajo cerkveno vme\u0161avanje.\",\"highlights\":[\"Dr\u017Eavljani so \u017Ee na posvetovalnem referendumu podprli tak\u0161no vsebino zakona.\",\"Avtor zagovarja pravico do prostovoljnega kon\u010Danja \u017Eivljenja in zavra\u010Da primerjave zakona z nacisti\u010Dnimi zlo\u010Dini.\",\"V pismu je izra\u017Eena podpora predlagateljem zakona in parlamentu, ki sta pripravila zakonsko podlago.\"]}}},{\"naslov\":\"Za prijazno smrt\",\"medij\":\"Mladina\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Luka Volk\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Odlo\u010Ditev, kako \u017Eeli \u010Dlovek umreti, ni stvar zdravni\u0161kih zdru\u017Eenj ali verskih skupnosti. To je povsem osebna odlo\u010Ditev.\",\"url\":null,\"id\":\"75.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek obravnava nasprotujo\u010Da si stali\u0161\u010Da verskih skupnosti, zdravni\u0161kih zdru\u017Eenj in posameznih strokovnjakov glede zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja pred prihajajo\u010Dim referendumom.\",\"highlights\":[\"Verske skupnosti in vrhovi zdravni\u0161kih zdru\u017Eenj ostro nasprotujejo zakonu, medtem ko ga \u0161tevilni upokojeni in aktivni zdravniki javno podpirajo.\",\"Nasprotniki svarijo pred u\u010Dinkom 'spolzkega klanca' in zlorabami, medtem ko zagovorniki poudarjajo pravico do avtonomije in dostojne smrti brez trpljenja.\",\"Javnomnenjske raziskave ka\u017Eejo, da velik del vernikov in dr\u017Eavljanov podpira mo\u017Enost pomo\u010Di pri kon\u010Danju \u017Eivljenja, kljub uradnim stali\u0161\u010Dem institucij.\"]},\"nasprotniki\":{\"povzetek\":\"Verske skupnosti in vodstva zdravni\u0161kih organizacij, kot je Zdravni\u0161ka zbornica, nasprotujejo zakonu z argumenti o nedotakljivosti \u017Eivljenja, medicinski etiki in nevarnosti sistemskih zlorab.\",\"highlights\":[\"\\\"Zakon se uvaja prehitro, \u0161e preden bi v Sloveniji sploh dovolj razvili in raz\u0161irili podro\u010Dje paliativne medicine.\\\"\",\"\\\"Vse to pa da bi lahko pomenilo ve\u010Dje mo\u017Enosti zlorab ter u\u010Dinek 'spolzkega klanca', po katerem bi se to podro\u010Dje postopoma liberaliziralo do nepredstavljivih skrajnosti.\\\"\",\"\\\"Zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja, o katerem bodo volivci odlo\u010Dali na referendumu 23. novembra, je v nasprotju z medicinsko etiko in Hipokratovo prisego.\\\"\",\"\\\"Uveljavitev ugovora vesti zaradi verskih ali drugih prepri\u010Danj bi privedla do prekinitve vezi med zdravnikom in pacientom v najpomembnej\u0161i to\u010Dki.\\\"\",\"\\\"Ali tudi vi menite, da je \u017Eivljenje nedotakljivo (17. \u010Dlen slovenske ustave) in da ga ni dovoljeno kon\u010Dati?\\\"\"]},\"podporniki\":{\"povzetek\":\"Zagovorniki zakona, med katerimi so dr. Du\u0161an Keber, dr. Anica Miku\u0161 Kos in dr. Josipina Ana \u010Cervek, izpostavljajo pomen osebne odlo\u010Ditve, so\u010Dutja in prepre\u010Devanja neznosnega trpljenja.\",\"highlights\":[\"\\\"Odlo\u010Ditev, kako \u017Eeli \u010Dlovek umreti, ni stvar zdravni\u0161kih zdru\u017Eenj ali verskih skupnosti. To je povsem osebna odlo\u010Ditev.\\\"\",\"\\\"Ko gre za soo\u010Denje s smrtjo, mora imeti vsak \u010Dlovek pravico izbire. Rad bi \u017Eivel v dr\u017Eavi, ki to pravico priznava in spo\u0161tuje.\\\"\",\"\\\"Paliativna oskrba se danes navaja kot eden glavnih razlogov za odla\u0161anje z uvedbo novega, prav tako nujnega in humanega procesa v slovensko zdravstvo.\\\"\",\"\\\"Smrt ni najhuj\u0161e, kar se zgodi \u010Dloveku. Dale\u010D pred njo je \u010Dlove\u0161ko trpljenje in \u0161e posebej trpljenje brez smisla.\\\"\",\"\\\"Zdravnik, ki pomaga pacientu pri kon\u010Danju \u017Eivljenja, ne kr\u0161i Hipokratove prisege. Ravno nasprotno \u2013 uresni\u010Duje njeno bistvo: 'ne \u0161kodovati'.\\\"\"]}}},{\"naslov\":\"Kon\u010Danje \u017Eivljenja ne celi ran\",\"medij\":\"Novice - slovenski tednik na Koro\u0161kem\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Hana Julija Kali\u0161nik\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"Na za\u010Detku \u0161tudija sem spoznala kolegico, s katero sva se veliko dru\u017Eili in se v pogovorih dotaknili tudi globljih tem.\",\"url\":null,\"id\":\"81.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Avtorica skozi osebno zgodbo o izgubi prijatelja zaradi evtanazije v tujini kriti\u010Dno razmi\u0161lja o tem, ali je asistiran samomor res odraz svobodne volje ali zgolj posledica pomanjkanja ljubezni in dru\u017Ebene podpore.\",\"highlights\":[\"Zgodba opisuje mladeni\u010Da s hudo depresijo, ki se je za evtanazijo odlo\u010Dil zaradi pomanjkanja sprejetosti v primarni dru\u017Eini.\",\"Avtorica postavlja vpra\u0161anje, ali je odlo\u010Ditev za smrt v stanju obupa in agonije dejansko odraz posameznikove svobodne volje.\",\"\u010Clanek poudarja, da bi morala dru\u017Eba in dr\u017Eava namesto omogo\u010Danja smrti zagotoviti bolj\u0161o psiholo\u0161ko podporo in bli\u017Eino ljudem v stiski.\"]},\"nasprotniki\":{\"povzetek\":\"Avtorica Hana Julija Kali\u0161nik nastopa kot kriti\u010Darka evtanazije, ki jo vidi kot na\u010Din izogibanja dru\u017Ebeni odgovornosti do trpe\u010Dih posameznikov.\",\"highlights\":[\"\\\"Asistiran samomor pa je marsikdaj na\u010Din, kako se izogniti tej odgovornosti.\\\"\",\"\\\"Ali je odlo\u010Ditev, ki jo \u010Dlovek sprejme v obupu, agoniji, res odraz njegove svobodne volje?\\\"\",\"\\\"To izgubo bi se dalo prepre\u010Diti. \u010Ce le evtanazija ne bi bila legalna?\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Napoved - tematski prispevki, 15. in 16. 11. (sobota in nedelja)\",\"medij\":\"sta.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"tep\/arh\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Napoved ozadij, tematskih prispevkov in pogovorov STA v soboto in nedeljo, 15. in 16. novembra.\",\"url\":\"https:\/\/www.sta.si\/3488113\",\"id\":\"82.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Slovenska tiskovna agencija napoveduje tematske prispevke za prihajajo\u010Di konec tedna, vklju\u010Dno z vsebino o kampanji pred referendumom o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"STA bo objavila tematski prispevek pred zadnjim tednom kampanje o referendumu o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"Napovedane so vsebine o Evropski prestolnici kulture Nova Gorica-Gorica in bo\u017Ei\u010Dnih sejmih po Evropi.\",\"Pripravljajo se pregledi dogajanja v dr\u017Eavnem zboru in na sodi\u0161\u010Dih za prihodnji teden.\"]},\"nasprotniki\":null,\"podporniki\":null}},{\"naslov\":\"Problemati\u010Dna referendumska agitacija vrha RKC\",\"medij\":\"novice.najdi.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Za zakonodajni referendum o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja se je na strani proti mo\u010Dno anga\u017Eirala tudi Cerkev.\",\"url\":\"https:\/\/novice.najdi.si\/novica\/098557ccab26a7c4c65ba0abfd2f37cf\",\"id\":\"83.pdf\",\"contents\":null},{\"naslov\":\"V novi Demokraciji preberite: Uveljavitev zakona o pomo\u010Di pri prostovoljnem\",\"medij\":\"novice.najdi.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Pi\u0161e: Petra Jan\u0161a Dr. Zvonka Zupani\u010D Slavec je \u017Ee dober mesec po nastopu Golobove vlade opozorila, da se v medijski ti\u0161ini pripravlja zakon o evtanaziji oziroma prostovoljni prekinitvi \u017Eivljenja. Tega je \u017Ee takrat pripravilo zdru\u017Eenje Srebrna nit in je nastalo zunaj zdravni\u0161kih organizacij (!). Dr. Zupani\u010D Slav\u010Deva je \u017Ee tedaj izpostavila, da so se vse [\u2026]\",\"url\":\"https:\/\/novice.najdi.si\/novica\/ce6a24d3d3f0a147f9e016227f47ce8d\",\"id\":\"84.pdf\",\"contents\":null},{\"naslov\":\"Zdravniki, pravniki in drugi strokovnjaki: zakaj glasovati proti asistiranemu\",\"medij\":\"novice.najdi.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"najdi.si\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Ekipa Zdravniki proti zakonu so posneli dvajsetminutni film Glas \u017Eivljenja. V njem so zbrali izjave ve\u010D zdravnikov in drugih zdravstvenih delavcev ter pravnikov in drugih strokovnjakov, ki opredelijo svoje mnenje, zakaj nasprotujejo zakonu o prostovoljnem kon\u010Danju \u017Eivljenja (PPK\u017D).\",\"url\":\"https:\/\/novice.najdi.si\/novica\/9711d5a3269c762412ba5519a3ca7a95\",\"id\":\"85.pdf\",\"contents\":null},{\"naslov\":\"Ta zakon prihaja v \u010Dasu, ko dr\u017Eava ne izpolnjuje osnovnih obveznosti do bolnih\",\"medij\":\"novice24.net\",\"datum\":\"14. 11. 2025\",\"avtor\":\"novice24.si\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Predstavniki zdravni\u0161kih in eti\u010Dnih organizacij so ob podpori Svetovnega zdravni\u0161kega zdru\u017Eenja znova opozorili, da bi predlagani zakon pomenil \u201Cnevaren dru\u017Ebeni eksperiment\u201D, ki ru\u0161i temeljna na\u010Dela me\",\"url\":\"https:\/\/novice24.net\/\/item\/2158353_ta-zakon-prihaja-v-\u010Dasu-ko-dr\u017Eava-ne-izpolnjuje-osnovnih-obveznosti-do-bolnih\",\"id\":\"86.pdf\",\"contents\":null},{\"naslov\":\"Zdravniki, pravniki in drugi strokovnjaki: zakaj glasovati proti asistiranemu\",\"medij\":\"druzina.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Spletno uredni\u0161tvo\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"\u00BBVsak potrebuje bli\u017Eino. Ta zakon tega ne daje,\u00AB pravi medicinska sestra Aja Ana Jelaska. FOTO: Zajem zaslona Ekipa Zdravniki proti zakonu so posneli dvajsetminutni film Glas \u017Eivljenja. V njem so zbrali izjave ve\u010D zdravnikov in drugih zdravstvenih delavcev ter pravnikov in drugih strokovnjakov, ki opredelijo svoje mnenje, zakaj nasprotujejo\",\"url\":\"https:\/\/www.druzina.si\/clanek\/smrt-ni-ustrezen-odziv-na-stiske-ljudi-video\",\"id\":\"87.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek predstavlja film Glas \u017Eivljenja, v katerem skupina zdravnikov, pravnikov in drugih strokovnjakov utemeljuje svoje nasprotovanje zakonu o prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Ekipa Zdravniki proti zakonu je posnela film, v katerem opozarjajo na resne posledice in nevarnosti predlagane zakonodaje.\",\"Strokovnjaki v prispevku izpostavljajo vpra\u0161anja etike, dostojanstva, ustavnosti in morebitnih zlorab pri izvajanju evtanazije.\",\"Namesto pomo\u010Di pri kon\u010Danju \u017Eivljenja sogovorniki pozivajo k zagotavljanju ustrezne paliativne in dolgotrajne oskrbe.\"]},\"nasprotniki\":{\"povzetek\":\"Skupina strokovnjakov pod imenom Zdravniki proti zakonu uporablja film za \u0161irjenje opozoril o zlorabah, protiustavnosti in ru\u0161enju odnosa med zdravnikom in bolnikom.\",\"highlights\":[\"\\\"Zakon ogro\u017Ea dostojanstvo, pove\u010Duje pritisk na ranljive in odpira vrata zlorabam.\\\"\",\"\\\"Zakon ves \u010Das govori samo o brezmejnem trpljenju in ne opredeli tega brezmejnega trpljenja, ga ne definira.\\\"\",\"\\\"Ta zakon, ki se obeta, je \u017Ee vzpostavil poru\u0161enje v odnosu med zdravnikom in bolnikom.\\\"\",\"\\\"Ena prvih stvari, ki me je zelo prizadela, je bil izra\u010Dun, koliko se prihrani pri evtanaziji starega, bolnega, nepokretnega \u010Dloveka. Osnovni motiv je bil verjetno '\u0161paranje'.\\\"\",\"\\\"Ustrezni odziv na stiske teh ljudi ni smrt, temve\u010D zagotavljanje ustrezne paliativne in dolgotrajne oskrbe.\\\"\",\"\\\"V Sloveniji sprejemamo zakon, ki je med bolj liberalnimi pri dolo\u010Danju pogojev zakaj ljudje lahko kandidirajo za evtanazijo.\\\"\",\"\\\"Kot zdravnica si nisem nikoli predstavljala, da se bom morala ukvarjati s problemom evtanazije.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"(VIDEO) Ve\u010Der za vikend z Markom Crnkovi\u010Dem: Koga bi volili, \u010De bi volili na\",\"medij\":\"vecer.com\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Matija Stepi\u0161nik\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Odgovorni urednik Ve\u010Dera Matija Stepi\u0161nik in kolumnist Marko Crnkovi\u010D debatirata o najbolj relevantnih politi\u010Dnih temah tega trenutka: od lex \u0160utar do volitev. Kaj vse se \u0161e lahko zgodi?\",\"url\":\"https:\/\/www.vecer.com\/slovenija\/video-vecer-za-vikend-z-markom-crnkovicem-koga-bi-volili-ce-bi-volili-na-martinovo-10397355\",\"id\":\"89.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek napoveduje vsebino Ve\u010Derovega podkasta in vikend izdaje \u010Dasopisa, kjer Matija Stepi\u0161nik in Marko Crnkovi\u010D analizirata aktualno politi\u010Dno dogajanje v Sloveniji.\",\"highlights\":[\"V podkastu avtorja razpravljata o razmerjih mo\u010Di pol leta pred volitvami in o stanju na slovenski politi\u010Dni sceni.\",\"Ena izmed osrednjih tem pogovora je pri\u010Dakovani razplet referenduma o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"Vikend izdaja prina\u0161a tudi kriti\u010Dno analizo interventnega '\u0160utarjevega zakona' s strani profesorja kazenskega prava dr. Zlatana De\u017Emana.\"]},\"nasprotniki\":null,\"podporniki\":{\"povzetek\":\"Urednik Matija Stepi\u0161nik in kolumnist Marko Crnkovi\u010D v okviru \u0161ir\u0161e politi\u010Dne analize naslavljata vpra\u0161anje razpleta referenduma o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"\\\"Kako se bo razpletel referendum o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja?\\\"\"]}}},{\"naslov\":\"(VIDEO) Ve\u010Der za vikend z Markom Crnkovi\u010Dem: Koga bi volili, \u010De bi volili na\",\"medij\":\"times.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"times.si\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Odgovorni urednik Ve\u010Dera Matija Stepi\u0161nik in kolumnist Marko Crnkovi\u010D debatirata o najbolj relevantnih politi\u010Dnih temah tega trenutka: od lex \u0160utar do volitev. Kaj vse se \u0161e lahko zgodi? NARO\u010CITE SE \u2026\",\"url\":\"https:\/\/www.times.si\/c\/ff8d9515b53ad795a1a1afd3e1638f9c88e5c5f2\/\",\"id\":\"91.pdf\",\"contents\":null},{\"naslov\":\"Ljudje volijo zase, ne glede na to, kaj s tem izvolijo za medicino\",\"medij\":\"delo.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Alojz Ihan\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Nevarna igra je posegati v strokovno avtonomijo, ki je temelj odgovornosti \u2013 v medicini predvsem odgovornosti do bolnika.\",\"url\":\"https:\/\/www.delo.si\/mnenja\/kolumne\/ljudje-volijo-zase-ne-glede-na-to-kaj-s-tem-izvolijo-za-medicino\",\"id\":\"92.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Avtor Alojz Ihan v \u010Dlanku kritizira vklju\u010Ditev asistence pri samomoru med redne zdravstvene storitve, saj meni, da zakonodajalec s tem grobo posega v strokovno avtonomijo in etiko medicinske stroke.\",\"highlights\":[\"Zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja uvaja asistenco pri samomoru kot obvezno zdravstveno storitev, kar je v nasprotju s tiso\u010Dletno medicinsko doktrino.\",\"Avtor opozarja, da bi morala dr\u017Eava namesto obremenjevanja javne zdravstvene mre\u017Ee ustanoviti specializirane centre zunaj rednega zdravstva, po vzoru \u0160vice in Avstrije.\",\"Prisila zdravstvenih delavcev k sodelovanju v postopkih kon\u010Danja \u017Eivljenja lahko vodi do \u0161tevilnih ugovorov vesti in pravnih sporov zaradi nejasnih klini\u010Dnih smernic.\"]},\"nasprotniki\":{\"povzetek\":\"Avtor Alojz Ihan in medicinska stroka opozarjata na neustreznost zakona, ki brez privolitve stroke uvaja asistenco pri samomoru kot dol\u017Enost zdravstvenih delavcev.\",\"highlights\":[\"\\\"Pisci zakona so si uresni\u010Ditev voliv\u010Deve \u017Eelje po asistirani samousmrtitvi zamislili (brez sodelovanja in pristanka medicinske stroke) le kot eno dodatno od ve\u010D tiso\u010D 'obi\u010Dajnih' zdravstvenih storitev.\\\"\",\"\\\"Pisci zakona so mimo privolitve stroke in v namen izvr\u0161ljivosti \u017Eelje volivca, potisnili zdravnike in zdravstvene delavce v enega najve\u010Djih doktrinarnih prelomov v medicinski zgodovini.\\\"\",\"\\\"Zakon namre\u010D nedvoumno uvaja zakonsko dol\u017Enost zdravnikov, medicinskih sester in drugih zdravstvenih delavcev, da sodelujejo v postopkih pomo\u010Di pri kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Zakon kot dol\u017Enost nalaga dejanje, ki izpolnjuje vse zakonske znake kaznivega dejanja pomo\u010Di pri samomoru.\\\"\",\"\\\"Zakonodajalec, ki je tako grobo in brez njihovega pristanka postavil zdravnike v vlogo izvr\u0161evalcev postopka za kon\u010Devanje \u017Eivljenja, bo te\u017Eko pridobil nazaj njihovo zaupanje.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona, vklju\u010Dno z volivci na referendumu in zakonodajalcem, zagovarjajo pravico posameznika do izbire pri kon\u010Danju \u017Eivljenja kot demokrati\u010Dno vrednoto.\",\"highlights\":[\"\\\"Slovenski volivec \u017Eeli imeti v rokah pravico do izbire, ki jo opisuje zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Slovenski volivec si, torej, v dolo\u010Denih okoli\u0161\u010Dinah, \u017Eeli imeti pravico do asistirane samousmrtitve!\\\"\",\"\\\"Volivec je v resnici ob odlo\u010Danju sledil le osnovnemu namenu zakona, to je misli na novo pravico, ki bi jo v stiski lahko uporabil.\\\"\"]}}},{\"naslov\":\"Ljudje volijo zase, ne glede na to, kaj s tem izvolijo za medicino\",\"medij\":\"delo.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Alojz Ihan\",\"oznaka\":[\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Nevarna igra je posegati v strokovno avtonomijo, ki je temelj odgovornosti \u2013 v medicini predvsem odgovornosti do bolnika.\",\"url\":\"https:\/\/www.delo.si\/mnenja\/mnenja\/kolumne\/ljudje-volijo-zase-ne-glede-na-to-kaj-s-tem-izvolijo-za-medicino\",\"id\":\"94.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Avtor Alojz Ihan v \u010Dlanku opozarja na nevarnost poseganja v strokovno avtonomijo zdravnikov, ki jo prina\u0161a predlagani zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja z uvrstitvijo asistence pri samomoru med redne zdravstvene storitve.\",\"highlights\":[\"Zakonodajalec je mimo privolitve stroke in brez posvetovanja z njo uvrstil asistenco pri samomoru med obvezne zdravstvene storitve.\",\"Avtor izpostavlja, da slovenski model, za razliko od \u0161vicarskega ali avstrijskega, sili zdravstvene delavce v vlogo neposrednih izvr\u0161evalcev postopka.\",\"Opozorilo, da bo neupo\u0161tevanje strokovne avtonomije vodilo v \u0161tevilne ugovore vesti in selitev strokovnih razprav v odvetni\u0161ke pisarne ter na sodi\u0161\u010Da.\"]},\"nasprotniki\":{\"povzetek\":\"Alojz Ihan kot predstavnik medicinske stroke kritizira zakonodajalca zaradi nasilnega posega v doktrino in avtonomijo zdravni\u0161tva brez predhodnega soglasja stroke.\",\"highlights\":[\"\\\"Nevarna igra je posegati v strokovno avtonomijo, ki je temelj odgovornosti \u2013 v medicini predvsem odgovornosti do bolnika.\\\"\",\"\\\"Pisci zakona so mimo privolitve stroke in v namen izvr\u0161ljivosti \u017Eelje volivca, potisnili zdravnike in zdravstvene delavce v enega najve\u010Djih doktrinarnih prelomov v medicinski zgodovini.\\\"\",\"\\\"Zakon namre\u010D nedvoumno uvaja zakonsko dol\u017Enost zdravnikov, medicinskih sester in drugih zdravstvenih delavcev, da sodelujejo v postopkih pomo\u010Di pri kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Zakonodajalec, ki je tako grobo in brez njihovega pristanka postavil zdravnike v vlogo izvr\u0161evalcev postopka za kon\u010Devanje \u017Eivljenja, bo te\u017Eko pridobil nazaj njihovo zaupanje.\\\"\",\"\\\"Vse napake v postopku, ki lahko pripeljejo do neizpolnjevanja zakonskih dolo\u010Dil, in s tem do ravnanja, ki je kaznivo, pa so zato breme zdravnikov.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona in volivci so v \u010Dlanku opisani kot tisti, ki si \u017Eelijo pravico do izbire in asistirane samousmrtitve kot novo dru\u017Ebeno in politi\u010Dno dejstvo.\",\"highlights\":[\"\\\"Slovenski volivec \u017Eeli imeti v rokah pravico do izbire, ki jo opisuje zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Slovenski volivec si, torej, v dolo\u010Denih okoli\u0161\u010Dinah, \u017Eeli imeti pravico do asistirane samousmrtitve!\\\"\",\"\\\"Volivec je v resnici ob odlo\u010Danju sledil le osnovnemu namenu zakona, to je misli na novo pravico, ki bi jo v stiski lahko uporabil.\\\"\"]}}},{\"naslov\":\"Problemati\u010Dna referendumska agitacija vrha RKC\",\"medij\":\"delo.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Uro\u0161 Esih\",\"oznaka\":[\"SREBRNA NIT\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Za zakonodajni referendum o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja se je na strani proti mo\u010Dno anga\u017Eirala tudi Cerkev.\",\"url\":\"https:\/\/www.delo.si\/novice\/slovenija\/problematicna-referendumska-agitacija-vrha-rkc\",\"id\":\"96.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica je na in\u0161pektorat prijavilo Nad\u0161kofijo Ljubljana zaradi domnevnih kr\u0161itev zakona o volilni in referendumski kampanji pri nasprotovanju zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Vrh Rimskokatoli\u0161ke cerkve se je mo\u010Dno anga\u017Eiral v kampanji proti zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"Sociolog dr. Marjan Smrke ocenjuje, da sta mobilizacija in argumentacija RKC v nekaterih delih problemati\u010Dni in zavr\u017Eni.\",\"Zavezni\u0161tvo, ki vklju\u010Duje koalicijske stranke in Srebrno nit, trdi, da je RKC s svojim delovanjem prestopila zakonske in ustavne okvire.\"]},\"nasprotniki\":{\"povzetek\":\"Rimskokatoli\u0161ka cerkev in Nad\u0161kofija Ljubljana se aktivno anga\u017Eirata proti zakonu, pri \u010Demer po mnenju kritikov uporabljata problemati\u010Dno in zakonsko sporno argumentacijo.\",\"highlights\":[\"Cerkev se je na strani proti zakonu mo\u010Dno anga\u017Eirala.\",\"Na\u010Din mobilizacije in argumentacija z vrhov slovenske Rimskokatoli\u0161ke cerkve (RKC) sta v primeru referenduma problemati\u010Dna.\",\"RKC je v kampanji po trditvah zavezni\u0161tva prestopila predvidene zakonske in ustavne okvire dovoljenega.\"]},\"podporniki\":{\"povzetek\":\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica, ki zdru\u017Euje koalicijske stranke in dru\u0161tvo Srebrna nit, zagovarja zakon in zahteva spo\u0161tovanje pravil referendumske kampanje.\",\"highlights\":[\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica zdru\u017Euje koalicijske stranke in Srebrno nit v podporo zakonu.\",\"Podali so prijavo na in\u0161pektorat za notranje zadeve zaradi kr\u0161itve zakona o volilni in referendumski kampanji zoper Nad\u0161kofijo Ljubljana.\",\"Zavezni\u0161tvo opozarja na nujnost spo\u0161tovanja zakonskih in ustavnih okvirov v \u010Dasu kampanje.\"]}}},{\"naslov\":\"Problemati\u010Dna referendumska agitacija vrha RKC\",\"medij\":\"delo.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Uro\u0161 Esih\",\"oznaka\":[\"SREBRNA NIT\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Za zakonodajni referendum o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja se je na strani proti mo\u010Dno anga\u017Eirala tudi Cerkev.\",\"url\":\"https:\/\/www.delo.si\/novice\/novice\/slovenija\/problematicna-referendumska-agitacija-vrha-rkc\",\"id\":\"97.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica je na in\u0161pektorat prijavilo Nad\u0161kofijo Ljubljana zaradi domnevnih kr\u0161itev zakonodaje o referendumski kampanji glede zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"V kampanji proti zakonu se je mo\u010Dno anga\u017Eirala Rimskokatoli\u0161ka cerkev (RKC), kar sociolog Marjan Smrke ozna\u010Duje za problemati\u010Dno in v nekaterih delih zavr\u017Eno.\",\"Zavezni\u0161tvo, ki zdru\u017Euje koalicijske stranke in dru\u0161tvo Srebrna nit, trdi, da je RKC s svojo mobilizacijo prestopila zakonske in ustavne okvire.\",\"Prijava na in\u0161pektorat za notranje zadeve je bila podana zaradi kr\u0161itve zakona o volilni in referendumski kampanji.\"]},\"nasprotniki\":{\"povzetek\":\"Rimskokatoli\u0161ka cerkev (RKC) se je aktivno vklju\u010Dila v kampanjo proti zakonu z mobilizacijo in argumentacijo, ki po mnenju kritikov presega dovoljene okvire.\",\"highlights\":[\"\\\"Za zakonodajni referendum o zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja se je na strani proti mo\u010Dno anga\u017Eirala tudi Cerkev.\\\"\",\"Na\u010Din mobilizacije in argumentacija z vrhov slovenske Rimskokatoli\u0161ke cerkve sta v primeru referenduma problemati\u010Dna in v nekaterih delih zavr\u017Ena.\",\"RKC je v kampanji domnevno prestopila predvidene zakonske in ustavne okvire dovoljenega.\"]},\"podporniki\":{\"povzetek\":\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica, ki vklju\u010Duje koalicijske stranke in Srebrno nit, zagovarja zakon in zahteva spo\u0161tovanje pravil referendumske kampanje.\",\"highlights\":[\"Zavezni\u0161tvo Moje \u017Eivljenje, moja pravica zdru\u017Euje koalicijske stranke in dru\u0161tvo Srebrna nit v podporo zakonu.\",\"Podporniki so na in\u0161pektorat za notranje zadeve podali prijavo zoper Nad\u0161kofijo Ljubljana zaradi kr\u0161itve zakona o volilni in referendumski kampanji.\",\"Zavezni\u0161tvo opozarja na nujnost spo\u0161tovanja zakonskih in ustavnih okvirov v javni razpravi o pomo\u010Di pri kon\u010Danju \u017Eivljenja.\"]}}},{\"naslov\":\"V novi Demokraciji preberite: Uveljavitev zakona o pomo\u010Di pri prostovoljnem\",\"medij\":\"demokracija.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Petra Jan\u0161a\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Pi\u0161e: Petra Jan\u0161a. Dr. Zvonka Zupani\u010D Slavec je \u017Ee dober mesec po nastopu Golobove vlade opozorila, da se v medijski ti\u0161ini pripravlja zakon o evtanaziji oziroma prostovoljni prekinitvi \u017Eivljenja. Tega...\",\"url\":\"https:\/\/demokracija.si\/uncategorized\/v-novi-demokraciji-preberite-uveljavitev-zakona-o-pomoci-pri-prostovoljnem-koncanju-zivljenja-je-treba-ustaviti\/\",\"id\":\"98.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek v tedniku Demokracija ostro nasprotuje uveljavitvi zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja in poziva k njegovi ustavitvi na prihajajo\u010Dem referendumu.\",\"highlights\":[\"Dr. Zvonka Zupani\u010D Slavec opozarja, da je zakon pripravilo zdru\u017Eenje Srebrna nit zunaj zdravni\u0161kih organizacij in v medijski ti\u0161ini.\",\"Referendum o uveljavitvi zakona, ki ga je dr\u017Eavni zbor sprejel 24. julija 2025, bo potekal 23. novembra.\",\"Za zavrnitev zakona na referendumu je potreben zavrnitveni kvorum v vi\u0161ini 339.205 glasov proti.\"]},\"nasprotniki\":{\"povzetek\":\"Nasprotniki zakona, vklju\u010Dno z dr. Zvonko Zupani\u010D Slavec in zdravni\u0161kimi organizacijami, trdijo, da zakon nedopustno posega v nedotakljivost \u017Eivljenja in sili zdravnike v usmrtitve.\",\"highlights\":[\"\\\"Nikakor ni dopustno, da se s predlogom tega zakona zdravnikom nalaga, da bi morali usmrtiti svoje bolnike, ki bi se za to odlo\u010Dili.\\\"\",\"\\\"Finan\u010Dna ozadja poseganja po \u017Eivljenju, ki so v predlogu zakona, so neprimerna, saj je \u017Eivljenje neprecenljivo.\\\"\",\"Nasprotniki menijo, da zakon \\\"posega v ustavno kategorijo nedotakljivosti \u017Eivljenja ter ustvarja pritisk na umirajo\u010De in bolne.\\\"\",\"\\\"Paradoksalno predlog celo zapi\u0161e, da mora zdravnik zaradi ugovora vesti poiskati drugega zdravnika, da to dejanje izvede.\\\"\",\"Dr. Zupani\u010D Slavec poudarja, da je zdravnik \\\"zavezan k ohranjanju \u017Eivljenja in izbolj\u0161evanju zdravja\\\".\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona, ki jih \u010Dlanek pripisuje 'slovenski levici' in vladajo\u010Di koaliciji, zagovarjajo pravico posameznika do avtonomne odlo\u010Ditve o koncu \u017Eivljenja.\",\"highlights\":[\"Podporniki zakona \\\"zagovarjajo pravico do odlo\u010Ditve o lastnem \u017Eivljenju in do dostojanstvene smrti.\\\"\",\"Zakon je pripravilo zdru\u017Eenje Srebrna nit.\",\"V referendumsko kampanjo je vklju\u010Denih 33 organizatorjev, med katerimi so tudi zagovorniki zakona.\"]}}},{\"naslov\":\"V novi Demokraciji preberite: Uveljavitev zakona o pomo\u010Di pri prostovoljnem\",\"medij\":\"demokracija.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Ga\u0161per Bla\u017Ei\u010D\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Pi\u0161e: Petra Jan\u0161a. Dr. Zvonka Zupani\u010D Slavec je \u017Ee dober mesec po nastopu Golobove vlade opozorila, da se v medijski ti\u0161ini pripravlja zakon o evtanaziji oziroma prostovoljni prekinitvi \u017Eivljenja. Tega je \u017Ee takrat pripravilo zdru\u017Eenje Srebrna nit in je nastalo\",\"url\":\"https:\/\/demokracija.si\/izpostavljeno\/v-novi-demokraciji-preberite-uveljavitev-zakona-o-pomoci-pri-prostovoljnem-koncanju-zivljenja-je-treba-ustaviti\/\",\"id\":\"100.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek v tedniku Demokracija ostro nasprotuje uveljavitvi zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja in poziva k njegovi zavrnitvi na prihajajo\u010Dem referendumu.\",\"highlights\":[\"Dr. Zvonka Zupani\u010D Slavec opozarja, da so se vse zdravni\u0161ke organizacije izrekle proti zakonu, saj je zdravnik zavezan k ohranjanju \u017Eivljenja.\",\"Referendum o zakonu bo potekal 23. novembra, za njegovo zavrnitev pa je potreben kvorum 339.205 glasov proti.\",\"Nasprotniki trdijo, da zakon posega v ustavno kategorijo nedotakljivosti \u017Eivljenja in ustvarja nedopusten pritisk na umirajo\u010De.\"]},\"nasprotniki\":{\"povzetek\":\"Nasprotniki zakona, vklju\u010Dno z dr. Zvonko Zupani\u010D Slavec in zdravni\u0161kimi organizacijami, poudarjajo eti\u010Dno nesprejemljivost evtanazije in pozivajo k dosegu zavrnitvenega kvoruma.\",\"highlights\":[\"\\\"Nikakor ni dopustno, da se s predlogom tega zakona zdravnikom nalaga, da bi morali usmrtiti svoje bolnike, ki bi se za to odlo\u010Dili.\\\"\",\"\\\"Finan\u010Dna ozadja poseganja po \u017Eivljenju, ki so v predlogu zakona, so neprimerna, saj je \u017Eivljenje neprecenljivo.\\\"\",\"\\\"Nasprotniki zakona menijo, da posega v ustavno kategorijo nedotakljivosti \u017Eivljenja ter ustvarja pritisk na umirajo\u010De in bolne.\\\"\",\"\\\"Paradoksalno predlog celo zapi\u0161e, da mora zdravnik zaradi ugovora vesti poiskati drugega zdravnika, da to dejanje izvede.\\\"\",\"\\\"Uveljavitev zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja je treba ustaviti!\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona, med katerimi sta zdru\u017Eenje Srebrna nit in vladajo\u010Da koalicija, zagovarjajo pravico posameznika do dostojanstvene smrti.\",\"highlights\":[\"\\\"Podporniki zakona pa zagovarjajo pravico do odlo\u010Ditve o lastnem \u017Eivljenju in do dostojanstvene smrti.\\\"\",\"Zakon je pripravilo zdru\u017Eenje Srebrna nit.\",\"Vladajo\u010Di so zakon s pomo\u010Djo posvetovalnega referenduma pripeljali do kon\u010Dnega odlo\u010Danja.\"]}}},{\"naslov\":\"V novi Demokraciji preberite: Uveljavitev zakona o pomo\u010Di pri prostovoljnem\",\"medij\":\"demokracija.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Petra Jan\u0161a\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Pi\u0161e: Petra Jan\u0161a. Dr. Zvonka Zupani\u010D Slavec je \u017Ee dober mesec po nastopu Golobove vlade opozorila, da se v medijski ti\u0161ini pripravlja zakon o evtanaziji oziroma prostovoljni prekinitvi \u017Eivljenja. Tega...\",\"url\":\"https:\/\/demokracija.si\/fokus\/v-novi-demokraciji-preberite-uveljavitev-zakona-o-pomoci-pri-prostovoljnem-koncanju-zivljenja-je-treba-ustaviti\/\",\"id\":\"102.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek v tedniku Demokracija poziva k ustavitvi uveljavitve zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja in napoveduje referendumsko odlo\u010Danje 23. novembra.\",\"highlights\":[\"Dr. Zvonka Zupani\u010D Slavec opozarja, da je bil zakon pripravljen v medijski ti\u0161ini in zunaj zdravni\u0161kih organizacij.\",\"Nasprotniki zakona trdijo, da predlog posega v ustavno kategorijo nedotakljivosti \u017Eivljenja in ustvarja pritisk na bolne.\",\"Zakon bo na referendumu zavrnjen, \u010De bo proti glasovalo ve\u010D volivcev kot za in bo dose\u017Een zavrnitveni kvorum 339.205 glasov.\"]},\"nasprotniki\":{\"povzetek\":\"Zdravni\u0161ke organizacije in dr. Zvonka Zupani\u010D Slavec ostro nasprotujejo zakonu, ki ga ozna\u010Dujejo za politi\u010Dno aktivnost slovenske levice, ki ogro\u017Ea nedotakljivost \u017Eivljenja.\",\"highlights\":[\"\\\"Nikakor ni dopustno, da se s predlogom tega zakona zdravnikom nalaga, da bi morali usmrtiti svoje bolnike, ki bi se za to odlo\u010Dili.\\\"\",\"\\\"Finan\u010Dna ozadja poseganja po \u017Eivljenju, ki so v predlogu zakona, so neprimerna, saj je \u017Eivljenje neprecenljivo.\\\"\",\"Nasprotniki menijo, da zakon \\\"posega v ustavno kategorijo nedotakljivosti \u017Eivljenja ter ustvarja pritisk na umirajo\u010De in bolne.\\\"\",\"\\\"Paradoksalno predlog celo zapi\u0161e, da mora zdravnik zaradi ugovora vesti poiskati drugega zdravnika, da to dejanje izvede.\\\"\"]},\"podporniki\":{\"povzetek\":\"Podporniki zakona, vklju\u010Dno z zdru\u017Eenjem Srebrna nit in vladajo\u010Do koalicijo, zagovarjajo pravico posameznika do dostojanstvene smrti.\",\"highlights\":[\"Podporniki zakona \\\"zagovarjajo pravico do odlo\u010Ditve o lastnem \u017Eivljenju in do dostojanstvene smrti.\\\"\",\"Zakon je pripravilo zdru\u017Eenje Srebrna nit.\",\"Vladajo\u010Di so zakon s pomo\u010Djo posvetovalnega referenduma pripeljali do kon\u010Dnega odlo\u010Danja.\"]}}},{\"naslov\":\"Nejc Povirk: \u201CLjudje se odlo\u010Dajo za smrt, ker se po\u010Dutijo osamljene, nemo\u010Dne in kot\",\"medij\":\"iskreni.net\",\"datum\":\"14. 11. 2025\",\"avtor\":\"Tadeja Zabret\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Z Nejcem Povirkom, poznavalcem zakonodaje s podro\u010Dja pomo\u010Di pri samomoru in evtanazije v tujini ter motorjem dru\u0161tva Usidrani, smo se poglobili v posledice tak\u0161ne zakonodaje v dru\u017Ebah, ki so pomo\u010D pri samomoru in evtanazijo\",\"url\":\"https:\/\/www.iskreni.net\/nejc-povirk-ljudje-se-odlocajo-za-smrt-ker-se-pocutijo-osamljene-nemocne-in-kot-breme\/\",\"id\":\"104.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"Intervju z Nejcem Povirkom iz dru\u0161tva Usidrani kriti\u010Dno obravnava predlog zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja in opozarja na njegove dolgoro\u010Dne dru\u017Ebene posledice.\",\"highlights\":[\"\u010Clanek izpostavlja mite o evtanaziji, kot je trditev, da bo zakon veljal le za terminalno bolne, in opozarja na \u0161irjenje definicij v tujini.\",\"Avtor poudarja, da se ljudje za smrt pogosto odlo\u010Dajo zaradi osamljenosti in ob\u010Dutka, da so breme, ne pa zaradi neznosnih fizi\u010Dnih bole\u010Din.\",\"Intervju izpostavlja pomanjkljiv nadzor nad predvideno komisijo in nevarnost, da evtanazija postane cenej\u0161a alternativa paliativni oskrbi.\"]},\"nasprotniki\":{\"povzetek\":\"Nejc Povirk in dru\u0161tvo Usidrani ostro nasprotujejo zakonu, pri \u010Demer uporabljajo taktiko razbijanja mitov in opozarjanja na zlorabe v tujini.\",\"highlights\":[\"\\\"Dr\u017Eave, ki so sprejele podobne zakone, so hitro raz\u0161irile definicijo,\\\" kar vklju\u010Duje tudi kombinacijo manj\u0161ih zdravstvenih stanj.\",\"\\\"Paliativa je draga, evtanazija cenej\u0161a,\\\" kar vodi v poslab\u0161anje paliativne oskrbe po uvedbi evtanazije.\",\"\\\"Strupi, ki se uporabljajo za usmrtitev, delujejo tako, da se plju\u010Da napolnijo z vodo, kar pomeni da se \u010Dlovek v praksi dlje \u010Dasa du\u0161i.\\\"\",\"\\\"V nobeni dr\u017Eavi varovalke niso delovale, kot je bilo obljubljeno,\\\" saj naj bi \u0161\u010Ditile izvajalce, ne pa ranljivih pacientov.\",\"\\\"Zakon je izjemno liberalen zato, ker kot klju\u010Dno na\u010Delo postavlja na\u010Delo avtonomije pacienta\\\" in eksplicitno govori o pravici do smrti.\",\"\\\"Vsi ti (v komisiji) bodo ideolo\u0161ko na isti strani, prepri\u010Dani, da je smrt sprejemljiv na\u010Din odre\u0161evanja trpljenja.\\\"\",\"\\\"Doslej je za pomo\u010D pri samomoru grozil zapor in smo samomor dojemali kot nekaj tragi\u010Dnega, ne kot krepost. Zdaj se ta logika obra\u010Da.\\\"\",\"\\\"Zakon, proti kateremu se borimo, tega ne prepre\u010Duje, svojci niti ne bodo nujno vedeli, da se je to zgodilo.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Novo mesto: Pogovor, proti pomo\u010Di pri samomoru\",\"medij\":\"moja-dolenjska.si\",\"datum\":\"14. 11. 2025\",\"avtor\":null,\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"V veliki dvorani Baragovega zavoda na Smre\u010Dnikovi 60 v Novem mestu bo v torek 18. novembra, potekal pogovor Proti pomo\u010Di pri samomoru.\",\"url\":\"https:\/\/moja-dolenjska.si\/novo-mesto-pogovor-proti-pomoci-pri-samomoru\/\",\"id\":\"108.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"V Novem mestu bo pred referendumom o evtanaziji potekal pogovorni ve\u010Der, na katerem bodo zdravniki in strokovni sodelavci predstavili razloge proti zakonu o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\",\"highlights\":[\"Dogodek z naslovom 'Proti pomo\u010Di pri samomoru' bo potekal 18. novembra v Baragovem zavodu.\",\"Na pogovoru bodo sodelovali zdravnici Alenka Forte in Alenka Simoni\u010D ter Jani Kramar iz dru\u0161tva Hospic.\",\"Referendum o zakonu, ki ga je sprejela vladna koalicija, bo potekal v nedeljo, 23. novembra.\"]},\"nasprotniki\":{\"povzetek\":\"Zdravniki in strokovnjaki nasprotujejo zakonu v sprejeti obliki, saj menijo, da je njihovo poslanstvo ohranjanje \u017Eivljenja in ne povzro\u010Danje smrti.\",\"highlights\":[\"\\\"Zakonu v tak\u0161ni obliki, kot ga je sprejela koalicija (Svoboda, SD in Levica) namre\u010D nasprotujejo zdravniki.\\\"\",\"\\\"Poudarjajo, da je njihova naloga zdravljenje, ne pa ubijanje.\\\"\",\"\\\"Zagovarjajo \u017Eivljenje in ne smrt.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"Odmevno: Zdravni\u0161tvo je vstalo, enotno, ko so jim ukazali moriti ljudi\",\"medij\":\"moja-dolenjska.si\",\"datum\":\"14. 11. 2025\",\"avtor\":null,\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"\u201CZdravni\u0161tvo je vstalo! Ne tedaj, ko so zdravnike poimenovali za dvo\u017Eivke in parazite in ne, ko so jih desetletja poni\u017Eevali za pogajalskimi mizami in v medijih! Tudi ne, ko so se lotili prostega \u010Dasa in jim prepovedali delati! Enotno\",\"url\":\"https:\/\/moja-dolenjska.si\/odmevno-zdravnistvo-je-vstalo-enotno-ko-so-jim-ukazali-moriti-ljudi\/\",\"id\":\"110.pdf\",\"contents\":{\"splosno\":{\"povzetek\":\"\u010Clanek poro\u010Da o mo\u010Dnem nasprotovanju zdravnikov in verskih skupnosti predlogu zakona o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja pred prihajajo\u010Dim referendumom.\",\"highlights\":[\"Zdravniki poudarjajo, da je njihovo poslanstvo zdravljenje in ne ubijanje, zato se mno\u017Ei\u010Dno upirajo zakonu.\",\"Dr. Bojanka \u0160tern navaja, da je ve\u010Dina zdravnikov zgro\u017Eena nad ukazom, da bi morali 'moriti ljudi'.\",\"Nasprotniki zakona namesto evtanazije predlagajo sprejetje zakona o paliativni oskrbi.\"]},\"nasprotniki\":{\"povzetek\":\"Zdravniki, verske skupnosti in dr. Bojanka \u0160tern ostro nasprotujejo zakonu, ki ga ozna\u010Dujejo za 'zakon o pomo\u010Di pri samomoru' in 'ukaz za morjenje ljudi'.\",\"highlights\":[\"\\\"Enotno smo vstali, ko so nam ukazali moriti ljudi!\\\"\",\"\\\"Gre za zakon o pomo\u010Di pri samomoru, evtanaziji, uradno lepo zapakirano v zakon o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Zakonu zdravniki nasprotujejo, navajajo, da je njihovo poslanstvo \u017Eivljenje, zdravljenje, in ne ubijanje.\\\"\",\"\\\"\u010Ce \u017Eelimo pomagati, potrebujemo Zakon o paliativni oskrbi in ne o pomo\u010Di pri prostovoljnem kon\u010Danju \u017Eivljenja.\\\"\",\"\\\"Zakonu nasprotujejo tudi vse verske skupnosti v Sloveniji.\\\"\",\"\\\"Tak\u0161nega spontanega gibanja v svoji dolgi profesionalni karieri ne pomnim.\\\"\"]},\"podporniki\":null}},{\"naslov\":\"V novi Demokraciji preberite: Uveljavitev zakona o pomo\u010Di pri prostovoljnem ...\",\"medij\":\"telex.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"Pi\u0161e: Petra Jan\u0161a Dr. Zvonka Zupani\u010D Slavec je \u017Ee dober mesec po nastopu Golobove vlade opozorila, da se v medijski ti\u0161ini pripravlja zakon o evtanaziji oziroma prostovoljni prekinitvi \u017Eivljenja. Tega je \u017Ee takrat pripravilo zdru\u017Eenje Srebrna nit in je nastalo zunaj zdravni\u0161kih organizacij (!). Dr. Zupani\u010D Slav\u010Deva je \u017Ee tedaj izpostavila, da so se vse\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5864173\",\"id\":\"112.pdf\",\"contents\":null},{\"naslov\":\"\u0160e ple\u0161ete? Zahvaljujo\u010D stranki Levica boste po novem financirali zavod za sodobni\",\"medij\":\"telex.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"EVTANAZIJA\"],\"intro\":\"V \u010Dasu, ko dru\u017Eine komaj shajajo, bolni otroci \u010Dakajo na donacije, cene osnovnih dobrin pa divje rastejo, se stranka Levica odlo\u010Di za ustanovitev javnega zavoda za sodobni ples \u2013 \u0161e enega nepotrebnega sesalca za davkopla\u010Devalski denar. Namesto re\u0161evanja pere\u010Dih te\u017Eav v zdravstvu, stanovanjski politiki ali poplavljenski obnovi, ministrica za kulturo\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5863956\",\"id\":\"113.pdf\",\"contents\":null},{\"naslov\":\"Odmevno: Zdravni\u0161tvo je vstalo, enotno, ko so jim ukazali moriti ljudi\",\"medij\":\"telex.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"EVTANAZIJA\",\"ZAKON O POMO\u010CI PRI PROSTOVOLJNEM KON\u010CANJU \u017DIVLJENJA\"],\"intro\":\"\u201CZdravni\u0161tvo je vstalo! Ne tedaj, ko so zdravnike poimenovali za dvo\u017Eivke in parazite in ne, ko so jih desetletja poni\u017Eevali za pogajalskimi mizami in v medijih! Tudi ne, ko so se lotili prostega \u010Dasa in jim prepovedali delati! Enotno smo vstali, ko so nam ukazali moriti ljudi!\u201D Tako je na X zapisala zdravnica dr. Bojanka\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5864208\",\"id\":\"114.pdf\",\"contents\":null},{\"naslov\":\"Dr. Ivan \u0160tuhec: Zakaj bi moral kdorkoli sodelovati pri evtanaziji?\",\"medij\":\"telex.si\",\"datum\":\"14. 11. 2025\",\"avtor\":\"telex.si\",\"oznaka\":[\"SREBRNA NIT\",\"EVTANAZIJA\"],\"intro\":\"Referendum Proti zastrupitvi in zlorabam bolnikov se pribli\u017Euje z nezadr\u017Eno hitrostjo. Tega spremlja vrsta eti\u010Dnih dilem, zato smo pred glasovanjem, ki bo potekalo naslednjo nedeljo, spregovorili z moralnim teologom dr. Ivanom \u0160tuhcem. Ta je predstavil nekaj klju\u010Dnih pomislekov \u2013 med drugim je za na\u0161e bralce obrazlo\u017Eil, kako bi uveljavitev pravice do\",\"url\":\"https:\/\/www.telex.si\/novica.php?n=5863954\",\"id\":\"115.pdf\",\"contents\":null}]}`;

